(window.__BOOKS=window.__BOOKS||{})["e_medea"]={"b":[["h2","Действующие лица"],["person","<span class=\"pn\">Кормилица</span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\">Дядька</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Медея, жена <span class=\"ch\" data-ch=\"yason\">Ясона</span></span> <span class=\"act-no\">(I)</span>"],["person","<span class=\"pn\">Хор коринфских женщин</span>"],["person","<span class=\"pn\">Креонт, царь Коринфа</span> <span class=\"act-no\">(III)</span> (на сцене — статисты)"],["person","<span class=\"pn\">Ясон, царь фессалийский</span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\">Эгей, царь афинский</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Вестник</span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\">Сыновья <span class=\"ch\" data-ch=\"medeya\">Медеи</span> и <span class=\"ch\" data-ch=\"yason\">Ясона</span> (II, III)</span>"],["place","Действие происходит в Коринфе, перед домом Медеи. Обычная декорация трагедии. Правый проход изображает улицу, ведущую к дворцам Креонта и Ясона, левый ведет в гавань и за границу."],["act","Пролог","a1",""],["sd","Утро. Из дома через левую дверь выходит кормилица."],["scene","Явление первое","s1",1,1],["sp","Кормилица"],["v","О, для чего крылатую ладью",0,1,0,0],["v","Лазурные, сшибался, утесы",0,1,0,0],["v","В Колхиду пропускали, ель зачем",0,1,0,0],["v","Та падала на Пелий, что вельможам,",0,1,0,0],["v","Их веслами вооружив, дала<a class=\"nr\" href=\"#n-k1\" data-n=\"k1\" aria-label=\"Примечание 1\">1</a>",0,2,0,0],["v","В высокий Иолк в злаченых завитках",0,3,0,0],["v","Руно царю Фессалии доставить?",0,4,0,0],["v","К его стенам тогда бы и моя",0,5,0,0],["v","Владычица не приплыла, Медея,",0,6,0,0],["v","<span class=\"ch\" data-ch=\"yason\">Ясона</span> полюбив безумно, — там",0,7,0,0],["v","Убить отца она не научала б",0,8,0,0],["v","Рожденных им и нежных Пелиад,",0,9,0,0],["v","И не пришлось бы ей теперь в Коринфе",0,10,0,1],["v","Убежища искать с детьми и мужем.",0,10,0,0],["v","Пусть гражданам успела угодить",0,11,0,0],["v","Она в изгнании, и мужу оставалась",0,12,0,0],["v","Покорною женой… (а разве есть",0,13,0,0],["v","На свете что милей семьи, где с мужем",0,14,0,0],["v","Живет жена согласно?), но удел",0,15,0,0],["v","<span class=\"ch\" data-ch=\"medeya\">Медеи</span> стал иной. Ее не любят,",0,15,0,0],["v","И нежные глубоко страждут узы.",0,16,0,0],["v","Детей <span class=\"ch\" data-ch=\"yason\">Ясон</span> и с матерью в обмен",0,17,0,0],["v","На новое отдать решился ложе,",0,18,0,0],["v","Он на царевне женится — увы!",0,19,0,0],["v","Оскорблена <span class=\"ch\" data-ch=\"medeya\">Медея</span>, и своих",0,20,0,1],["v","Остановить она не хочет воплей.",0,20,0,0],["v","Она кричит о клятвах и руки",0,21,0,0],["v","Попранную зовет обратно верность,",0,22,0,0],["v","Богов зовет в свидетели она",0,22,0,0],["v","Ясоновой расплаты.",0,23,0,0],["v","И на ложе,",1,23,0,0],["v","От пищи отказавшись, ночь и день",0,24,0,0],["v","Отдавши мукам тело, сердцу таять",0,25,0,0],["v","В слезах дает царица с той поры,",0,25,0,0],["v","Как злая весть обиды поселилась",0,26,0,0],["v","В ее душе. Не поднимая глаз",0,27,0,0],["v","Лица, к земле склоненного, Медея,",0,27,0,0],["v","Как волн утес, не слушает друзей,",0,28,0,0],["v","В себя прийти не хочет. Лишь порою,",0,29,0,0],["v","Откинув шею белую, она",0,30,0,1],["v","Опомнится как будто, со слезами",0,30,0,0],["v","Мешая имя отчее и дома",0,31,0,0],["v","Родного, и земли воспоминанье,",0,32,0,0],["v","И все, чему безумно предпочла",0,32,0,0],["v","Она ее унизившего мужа.",0,33,0,0],["v","Несчастие открыло цену ей",0,34,0,0],["v","Утраченной отчизны.",0,35,0,0],["v","Дети даже",1,35,0,0],["v","Ей стали ненавистны, и на них",0,35,0,0],["v","Глядеть не может мать. Мне страшно, как бы",0,36,0,0],["v","Шальная мысль какая не пришла",0,37,0,0],["v","Ей в голову. Обид не переносит",0,37,0,0],["v","Тяжелый ум, и такова <span class=\"ch\" data-ch=\"medeya\">Медея</span>.",0,38,0,0],["v","И острого мерещится удар",0,39,0,0],["v","Невольно мне меча, разящий печень,",0,40,0,1],["v","Там над открытым ложем, — и боюсь,",0,40,0,0],["v","Чтобы, царя и молодого мужа",0,41,0,0],["v","Железом поразивши, не пришлось",0,42,0,0],["v","Ей новых мук отведать горше этих.",0,43,0,0],["v","Да, грозен гнев <span class=\"ch\" data-ch=\"medeya\">Медеи</span>: не легко<a class=\"nr\" href=\"#n-k2\" data-n=\"k2\" aria-label=\"Примечание 2\">2</a>",0,43,0,0],["v","Ее врагу достанется победа.",0,44,0,0],["v","Но мальчиков я вижу — бег они",0,45,0,0],["v","Окончили привычный и домой",0,46,0,0],["v","Идут теперь спокойно. А до муки",0,46,0,0],["v","И дела нет им материнской. Да,",0,47,0,0],["v","Страдания детей не занимают.",0,48,0,0],["scene","Явление второе","s2",1,2],["sd","Справа старый дядька ведет двух мальчиков. Кормилица, дядька и дети."],["sp","Дядька"],["v","О старая царицына раба!",0,49,0,0],["v","Зачем ты здесь одна в воротах? Или",0,50,0,1],["v","Самой себе ты горе поверяешь?",0,50,0,0],["v","<span class=\"ch\" data-ch=\"medeya\">Медея</span> ж как рассталася с тобой?",0,51,0,0],["sp","Кормилица"],["v","О старый спутник сыновей <span class=\"ch\" data-ch=\"yason\">Ясона</span>!",0,52,0,0],["v","Для добрых слуг несчастие господ",0,53,0,0],["v","Не то же ли, что и свое: за сердце",0,54,0,0],["v","Цепляется оно, и до того",0,55,0,0],["v","Измучилась я, веришь, что желанье,",0,55,0,0],["v","Уж и сама не знаю как, во мне",0,56,0,0],["v","Явилось рассказать земле и небу",0,57,0,0],["v","Несчастия царицы нашей.",0,58,0,0],["sp","Дядька"],["v","Плачет,",1,58,0,0],["v","Поди, еще?..",0,59,0,0],["sp","Кормилица"],["v","Наивен ты, старик,",1,59,0,0],["v","Ведь горе то лишь началось, далеко",0,60,0,1],["v","И полпути не пройдено.",0,60,0,0],["sp","Дядька"],["v","Слепая…",1,60,0,0],["v","Не про господ будь сказано. Своих,",0,61,0,0],["v","Должно быть, бед она не знает новых.",0,62,0,0],["sp","Кормилица"],["dir","живо приближаясь к нему"],["v","Каких? Каких? О, не скупись — открой…",0,62,0,0],["sp","Дядька"],["v","Нет, ничего. Так, с языка сорвалось.",0,63,0,0],["sp","Кормилица"],["dir","с жестом мольбы"],["v","О, не таи! Касаясь бороды,",0,64,0,0],["v","Тебя молю: открой подруге рабства.",0,65,0,0],["v","Ведь, если нужно, мы и помолчать",0,65,0,0],["v","Сумели бы…",0,66,0,0],["sp","Дядька"],["v","Я слышал, — но и виду<a class=\"nr\" href=\"#n-k3\" data-n=\"k3\" aria-label=\"Примечание 3\">3</a>",1,66,0,0],["v","Не подал я, что слышу, проходя",0,67,0,0],["v","У Камешков сегодня, знаешь, где",0,67,0,0],["v","Старейшины сидят близ вод священных<a class=\"nr\" href=\"#n-k4\" data-n=\"k4\" aria-label=\"Примечание 4\">4</a>",0,68,0,0],["v","Пирены. Кто-то говорил, что царь",0,69,0,0],["v","Сбирается детей с <span class=\"ch\" data-ch=\"medeya\">Медеей</span> вместе",0,70,0,1],["v","Коринфского лишить приюта. Слух",0,71,0,0],["v","Тот верен ли, не знаю: лучше б, если",0,72,0,0],["v","Неверен был он.",0,73,0,0],["sp","Кормилица"],["v","Что же, и <span class=\"ch\" data-ch=\"yason\">Ясон</span>",1,73,0,0],["v","До этого допустит? Хоть и в ссоре",0,74,0,0],["v","Он с матерью, но дети ведь его же…",0,75,0,0],["sp","Дядька"],["v","Что ж? Новая жена всегда милей:",0,76,0,0],["v","О прежней царь семье не помышляет.",0,77,0,0],["sp","Кормилица"],["v","Погибли мы… коль, давешней беды",0,78,0,0],["v","Не вычерпав, еще и эту впустим…",0,79,0,0],["sp","Дядька"],["v","Все ж госпоже ее не время знать:",0,80,0,1],["v","Ты затаишь мои слова покуда.",0,80,0,0],["sp","Кормилица"],["dir","к детям, обнимая их"],["v","Вот, дети! Вот каков отец для вас!",0,81,0,0],["v","Но боги да хранят его! Над нами",0,82,0,0],["v","Он господин, — хоть, кажется, нельзя,",0,83,0,0],["v","Чтоб человек больней семью обидел.",0,84,0,0],["sp","Дядька"],["v","В природе смертных это. Человек",0,85,0,0],["v","Всегда себя сильней, чем друга, любит.",0,85,0,0],["v","Иль новость ты узнала, удивляюсь…",0,86,0,0],["v","И должен был для этого <span class=\"ch\" data-ch=\"yason\">Ясон</span>",0,87,0,0],["v","Пожертвовать детьми утехам ложа?..",0,88,0,0],["sp","Кормилица"],["v","Идите с богом, дети, — все авось",0,89,0,0],["v","Уладится. А ты, старик, подальше",0,90,0,1],["v","Держи детей от матери — она",0,90,0,0],["v","Расстроена. Запечатлелась ярость",0,91,0,0],["v","В ее чертах — и как бы на своих",0,92,0,0],["v","Не вылилась она, увы! Не стихнет",0,92,0,0],["v","Без жертвы гнев ее — я знаю. Только",0,93,0,0],["v","Пускай бы враг то был, а не свои…",0,94,0,0],["sd","Педагог уходит в дверь направо. Кормилица удерживает детей еще на несколько минут."],["scene","Парод","s3",1,3],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["dir","за сценой"],["v","Увы!<a class=\"nr\" href=\"#n-k5\" data-n=\"k5\" aria-label=\"Примечание 5\">5</a>",0,95,0,0],["v","О, злы мои страданья. О!",0,95,0,0],["v","О, смерть! Увы! О, злая смерть!",0,96,0,0],["scene","Явление третье","s4",1,4],["sd","Без дядьки."],["sp","Кормилица"],["dir","то прижимая к себе детей, то подвигая их к правой двери, куда ушел дядька"],["v","Началось… О дети… Там мать,",0,97,0,0],["v","Ваша мать свое сердце — увы! —",0,97,0,0],["v","Мечет по воле и гнев",0,98,0,0],["v","Ярый катает… Подальше",0,99,0,0],["v","Затаитесь, милые. Глаз",0,100,0,1],["v","Не надо тревожить ее…",0,100,0,0],["v","Ни на шаг к ней ближе, о дети:",0,101,0,0],["v","Вы души ее гордой, и дикой,",0,102,0,0],["v","И охваченной гневом бегите…",0,103,0,0],["v","О, скорее, скорее под кровлю…",0,104,0,0],["sd","(Вталкивает их в дверь.)"],["v","Это облако стона сейчас",0,105,0,0],["v","Раскаленная злоба ее",0,106,0,0],["v","Подожжет… Где предел для тебя,",0,107,0,0],["v","О сердце великих дерзаний,",0,108,0,0],["v","Неутешное сердце, коль мука",0,109,0,0],["v","Тебя ужалила, сердце?",0,110,0,1],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["dir","все еще за сценой"],["v","О, горе! О, муки! О, муки и вы,",0,110,0,0],["v","Бессильные стоны! Вы, дети…",0,111,0,0],["v","О, будьте ж вы прокляты вместе",0,112,0,0],["v","С отцом, который родил вас!",0,112,0,0],["v","Весь дом наш погибни!<a class=\"nr\" href=\"#n-k6\" data-n=\"k6\" aria-label=\"Примечание 6\">6</a>",0,113,0,0],["sp","Кормилица"],["v","На голову нашу — увы! —",0,114,0,0],["v","Слова эти… Горе, о, горе!",0,115,0,0],["v","Что ж сделали дети тебе?",0,115,0,0],["v","Они за отца в ответе ль? Что мечешь",0,116,0,0],["v","Ты гнев на детей! О милые, я",0,117,0,0],["v","Боюсь за судьбу вашу, дети,",0,117,0,0],["v","Ужасны порывы царей,",0,118,0,0],["v","Так редко послушных другим,",0,119,0,0],["v","Так часто всевластных…",0,120,0,1],["v","Их злобе легко не уняться…",0,120,0,0],["v","Не лучше ли быть меж листов",0,121,0,0],["v","Невидным листом?",0,122,0,0],["v","О, как бы хотела дождаться",0,123,0,0],["v","Я старости мирной вдали",0,124,0,0],["v","От царской гордыни…",0,125,0,0],["v","Умеренность — сладко звучит",0,125,0,0],["v","И самое слово, а в жизни",0,126,0,0],["v","Какое сокровище в нем!",0,127,0,0],["v","Избыток в разладе с удачей,",0,128,0,0],["v","И горшие беды на род",0,129,0,0],["v","С божественным гневом влечет он.",0,130,0,1],["sd","На орхестру спускается хор из 15 коринфских женщин."],["sp","Хор"],["v","Парод Я слышала голос, я слышала крик",0,131,0,0],["v","Несчастной жены из дальней Колхиды:",0,132,0,0],["v","Еще ли она, скажи, не смирилась?",0,133,0,0],["v","Скажи мне, старуха…",0,134,0,0],["v","Чрез двери двойные я слышала стон<a class=\"nr\" href=\"#n-k7\" data-n=\"k7\" aria-label=\"Примечание 7\">7</a>",0,135,0,0],["v","И скорби семьи сострадаю,",0,136,0,0],["v","Сердцу давно уже милой.",0,137,0,0],["sp","Кормилица"],["v","Той нет уж семьи — распалась она:",0,138,0,0],["v","Мужа — ложе тиранов,<a class=\"nr\" href=\"#n-k8\" data-n=\"k8\" aria-label=\"Примечание 8\">8</a>",0,140,0,1],["v","Терем жену утаил,",0,140,0,0],["v","Царицу мою с тающим сердцем,",0,141,0,0],["v","Лаской ничьей, ни единого друга",0,142,0,0],["v","Лаской она не согрета…",0,143,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["dir","за сценой"],["v","О, ужас! О, ужас!",0,143,0,0],["v","О, пусть небесный перун",0,144,0,0],["v","Пронижет мне череп!..",0,145,0,0],["v","О, жить зачем мне еще?",0,146,0,0],["v","Увы мне! Увы! Ты, смерть, развяжи",0,146,0,0],["v","Мне жизни узлы — я ее ненавижу…",0,147,0,0],["sp","Хор"],["str","Строфа"],["v","Ты внял ли, о Зевс, ты, матерь Земля, ты, Солнце,",0,148,0,0],["v","Стонам печальным",0,149,0,0],["v","Злосчастной невесты?",0,150,0,1],["v","Безумны уста, вы — зачем",0,150,0,0],["v","Желанье холодного ложа?",0,151,0,0],["v","Смерти шаги",0,152,0,0],["v","Разве замедлят?",0,152,0,0],["v","Надо ль молить ее?",0,153,0,0],["v","Если твой муж пожелал",0,154,0,0],["v","Нового ложа, зачем же",0,154,0,0],["v","Гневом бедствие это",0,155,0,0],["v","Хочешь ты углубить,",0,156,0,0],["v","Частое в мире? Кронид",0,156,0,0],["v","Правде твоей поможет:",0,157,0,0],["v","Только не надо сердце, жена,",0,158,0,0],["v","Сердце в слезах не надо топить",0,158,0,0],["v","По муже неверном…",0,159,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["dir","за сценой"],["v","Великий Кронид… Фемида-царица!<a class=\"nr\" href=\"#n-k9\" data-n=\"k9\" aria-label=\"Примечание 9\">9</a>",0,160,0,1],["v","О, призрите, боги, на муки мои!",0,160,0,0],["v","Сама я великой клятвой",0,161,1,0],["v","Проклятого мужа",0,161,1,0],["v","Связала с собою, увы!",0,162,1,0],["v","О, если б теперь",0,163,1,0],["v","Его и с невестой увидеть —",0,163,1,0],["v","Два трупа в обломках чертога!",0,164,1,0],["v","От них обиды, от них",0,165,1,0],["v","Начало… О боги… О ты,",0,165,1,0],["v","Отец мой, о город, от вас я",0,166,1,0],["v","Постыдно бежала, и труп",0,166,1,0],["v","Родимого брата меж нами.",0,167,1,0],["sp","Кормилица"],["v","Слушайте, что говорит,",0,168,0,0],["v","Вопли мечет какие",0,168,0,0],["v","Фемиде, обетов царице,",0,169,0,0],["v","И Зевсу, кравчему клятвы.",0,170,0,1],["v","Ужасной, ужасной она",0,170,0,0],["v","Местью насытит сердце.",0,171,0,0],["sp","Хор"],["str","Антистрофа"],["v","Зачем же она явить нам лицо не хочет?",0,172,0,0],["v","Слух не приклонит",0,173,0,0],["v","На нежный мой голос?",0,173,0,0],["v","Безумную злобу ее,",0,174,0,0],["v","Души ее темное пламя,",0,175,0,0],["v","Может быть, я",0,176,0,0],["v","И утишила б",0,176,0,0],["v","Словом и лаской.",0,177,0,0],["v","Пусть же любимые мной",0,178,0,0],["v","Видят желание сердца…",0,179,0,0],["sd","(Кормилице.)"],["v","К ней в чертог не войдешь ли?",0,180,0,1],["v","Пусть она выйдет к нам…",0,180,0,0],["v","Медлить не надо… Скорей!",0,181,0,0],["v","Может сейчас несчастье",0,182,0,0],["v","В этих стенах произойти…",0,182,0,0],["v","Страшен порыв гнева и мести,",0,183,0,0],["v","Отчаянье страшно.",0,184,0,0],["sp","Кормилица"],["v","Пойти я готова… Но только",0,184,0,0],["v","Царицу смогу ль образумить?",0,185,0,0],["v","Труда ж и желаний не жалко…",0,186,0,0],["v","Как львица в муках родильных,",0,186,0,0],["v","Так дико глядит она, если",0,187,0,0],["v","С словами на робких устах",0,188,0,0],["v","Приблизится к ложу рабыня…",0,188,0,0],["v","О да, не будет ошибкой",0,189,1,0],["v","Сказать, что ума и искусства",0,190,1,1],["v","Немного те люди явили,",0,190,1,0],["v","Которые некогда гимны",0,191,1,0],["v","Слагали, чтоб петь за столами",0,192,1,0],["v","На пире священном иль просто",0,192,1,0],["v","Во время обеда, балуя",0,193,1,0],["v","Мелодией уши счастливых…",0,194,1,0],["v","Сказать, что никто не придумал",0,195,1,0],["v","Гармонией лир многострунных",0,195,1,0],["v","Печали предел ненавистной,",0,196,1,0],["v","Печали, рождающей смерти,",0,197,1,0],["v","Колеблющей ужасом царства,",0,197,1,0],["v","Печали предел положить…",0,198,1,0],["v","Лечиться мелодией людям",0,199,1,0],["v","Полезно бы было, на пире",0,200,1,1],["v","Напрасны труды музыканта:",0,200,1,0],["v","Уставленный яствами стол",0,201,1,0],["v","Без музыки радует сердце.",0,202,1,0],["sd","(Уходит в левую дверь.)"],["sd","За сценой стоны."],["sp","Хор"],["str","Эпод"],["v","Я слышу опять",0,203,0,0],["v","Плачущий голос ее,",0,203,0,0],["v","Ее протяжные стоны.",0,204,0,0],["v","На мужа проклятьями с ложа,",0,205,0,0],["v","Воздух пронзая,",0,206,0,0],["v","Вопли несутся. Фемиду зовет",0,206,0,0],["v","Несчастное чадо Колхиды,",0,207,0,0],["v","Зачем увлекала ее",0,208,0,0],["v","Чрез моря теснину на брег",0,209,0,0],["v","Эллады, туда,",0,210,0,1],["v","Где волны катает",0,210,0,0],["v","Пучина, и нет ей предела.",0,211,0,0],["act","Действие первое","a2","I"],["scene","Явление четвертое","s5",2,5],["sd","Из средних дверей выходит с небольшою свитою рабынь в восточных одеждах <span class=\"ch\" data-ch=\"medeya\">Медея</span>; у нее длинный овал лица, матовые черные волосы, тип лица грузинский, шафранного цвета и затканная одежда напоминает Восток. <span class=\"ch\" data-ch=\"medeya\">Медея</span> и хор."],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["dir","к хору"],["v","О дочери Коринфа, если к вам",0,212,0,0],["v","И вышла я, так потому, что ваших",0,213,0,0],["v","Упреков не хочу. Иль мало есть",0,213,0,0],["v","Прослывших гордецами оттого лишь,",0,214,0,0],["v","Что дом милей им площади иль видеть",0,215,0,0],["v","Они горят иные страны? Шум",0,216,0,0],["v","Будь людям ненавистен, и сейчас",0,216,0,0],["v","Порочными сочтут их иль рукою",0,217,0,0],["v","Махнувшими на все. Как будто суд",0,218,0,0],["v","Глазам людей принадлежит, и смеем",0,219,0,0],["v","Мы осудить, не распознав души,",0,220,0,1],["v","Коль человек ничем нас не обидел.",0,220,0,0],["v","Уступчивым, конечно, должен быть",0,221,0,0],["v","Меж вас чужой всех больше, но и граждан",0,222,0,0],["v","Заносчивых не любят, не дают",0,223,0,0],["v","Они узнать себя и тем досадны…",0,223,0,0],["v","Но на меня, подруги, и без вас<a class=\"nr\" href=\"#n-k10\" data-n=\"k10\" aria-label=\"Примечание 10\">10</a>",0,224,0,0],["v","Нежданное обрушилось несчастье.",0,225,0,0],["v","Раздавлена я им и умереть",0,226,0,0],["v","Хотела бы — дыханье только мука:",0,226,0,0],["v","Все, что имела я, слилось в одном,",0,227,0,0],["v","И это был мой муж, — и я узнала,",0,228,0,0],["v","Что этот муж — последний из людей.",0,229,0,0],["sd","Пауза."],["v","Да, между тех, кто дышит и кто мыслит,",0,230,0,1],["v","Нас, женщин, нет несчастней. За мужей",0,230,0,0],["v","Мы платим — и не дешево. А купишь,",0,231,0,0],["v","Так он тебе хозяин, а не раб.<a class=\"nr\" href=\"#n-k11\" data-n=\"k11\" aria-label=\"Примечание 11\">11</a>",0,232,0,0],["v","И первого второе горе больше.",0,233,0,0],["v","А главное — берешь ведь наобум:",0,234,0,0],["v","Порочен он иль честен, как узнаешь.",0,235,0,0],["v","А между тем уйди — тебе ж позор,",0,235,0,0],["v","И удалить супруга ты не смеешь.",0,236,0,0],["v","И вот жене, вступая в новый мир,",0,237,0,0],["v","Где чужды ей и нравы и законы,",0,238,0,0],["v","Приходится гадать, с каким она",0,239,0,0],["v","Постель созданьем делит. И завиден",0,240,0,1],["v","Удел жены, коли супруг ярмо",0,241,0,0],["v","Свое несет покорно. Смерть иначе.",0,242,0,0],["v","Ведь муж, когда очаг ему постыл,",0,243,0,0],["v","На стороне любовью сердце тешит,",0,244,0,0],["v","У них друзья и сверстники, а нам",0,245,0,0],["v","В глаза глядеть приходится постылым.",0,246,0,0],["v","Но говорят, что за мужьями мы,",0,247,0,0],["v","Как за стеной, а им, мол, копья нужны.",0,248,0,0],["v","Какая ложь! Три раза под щитом",0,250,0,1],["v","Охотней бы стояла я, чем раз",0,250,0,0],["v","Один родить. — Та речь вообще о женах…",0,251,0,0],["v","Но вы и я, одно ли мы? У вас",0,252,0,0],["v","И город есть, и дом, и радость жизни;",0,253,0,0],["v","Печальны вы — вас утешает друг,",0,253,0,0],["v","А я одна на свете меж чужими",0,254,0,0],["v","И изгнана и брошена.",0,255,0,0],["v","Росла",1,255,0,0],["v","Меж варваров, вдали я: здесь ни дома,",0,256,0,0],["v","Ни матери, ни брата — никого,",0,256,0,0],["v","Хоть бы одна душа, куда причалить",0,257,0,0],["v","Ладью на время бури.",0,258,0,0],["v","Но от вас",1,258,0,0],["v","Немногого прошу я. Если средство",0,259,0,0],["v","Иль путь какой найду я отомстить",0,260,0,1],["v","За все несчастья мужу, — не мешайтесь",0,260,0,0],["v","И, главное, молчите. Робки мы,",0,261,0,0],["v","И вид один борьбы или железа",0,262,0,0],["v","Жену страшит. Но если брачных уз",0,263,0,0],["v","Коснулася обида, кровожадней",0,264,0,0],["v","Не сыщете вы сердца на земле.",0,265,0,0],["sp","Корифей"],["v","Все сделаю, Медея, справедливым",0,266,0,0],["v","Желаниям и скорби не дивлюсь",0,267,0,0],["v","Твоей, жена, я больше. Но <span class=\"ch\" data-ch=\"kreont\">Креонта</span>,",0,268,0,0],["v","Царя земли я вижу этой, — он",0,269,0,0],["v","Не новое ль объявит нам решенье?",0,270,0,1],["scene","Явление пятое","s6",2,6],["sd","Те же и <span class=\"ch\" data-ch=\"kreont\">Креонт</span> со свитой и скипетром. Он еще не стар. Вид и голос человека рассеянного, живущего порывами и впечатлениями. Голосу не хватает уверенности. Он приходит со стороны своего дворца."],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["dir","к <span class=\"ch\" data-ch=\"medeya\">Медее</span>"],["v","Ты, мрачная, на мужа тяжкий гнев",0,270,0,0],["v","Скопившая, Медея, говорю я",0,271,0,0],["v","С тобой, и вот о чем: земли моей",0,272,0,0],["v","Пределы ты покинешь, взяв обоих",0,273,0,0],["v","Детей с собой, не медля… а приказ",0,273,0,0],["v","Исполнишь ты",0,274,0,0],["sd","(стукнув скипетром о землю)"],["v","при мне, и двери дома",0,275,4,0],["v","Своей я не увижу прежде, чем",0,276,0,0],["v","Не выброшу тебя отсюда, слышишь?",0,276,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Ай! Ай! Несчастная, я гибну. Недруг наш",0,277,0,0],["v","Весь выпустил канат, и мне на берег",0,278,0,0],["v","От злой волны уже спасенья нет…",0,279,0,0],["v","Но тяжкая оставила мне силы",0,280,0,1],["v","Спросить тебя: за что ты гонишь нас?",0,280,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","О, тайны нет тут никакой: боюсь я,",0,281,0,0],["v","Чтоб дочери неисцелимых зол",0,282,0,0],["v","Не сделала ты, женщина, моей.",0,283,0,0],["v","Во-первых, ты хитра, и чар не мало",0,283,0,0],["v","Твой ум постиг, к тому же ты теперь",0,284,0,0],["v","Без мужа остаешься и тоскуешь…",0,285,0,0],["v","Я слышал даже, будто ты грозишь",0,286,0,0],["v","И мне, и жениху с невестой чем-то.",0,286,0,0],["v","Так вот, пока мы целы, и хочу",0,287,0,0],["v","Я меры взять. Пусть лучше ненавистен",0,288,0,0],["v","<span class=\"ch\" data-ch=\"medeya\">Медее</span> я, чем каяться потом",0,289,0,0],["v","В мягкосердечии.",0,290,0,1],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Увы! Увы! Увы!",0,290,0,0],["v","О, не впервые, царь, и сколько раз",0,291,0,0],["v","Вредила мне уж эта слава: зол",0,292,0,0],["v","Она — источник давний.",0,293,0,0],["v","Если смыслом",1,293,0,0],["v","Кто одарен, софистов из детей",0,294,0,0],["v","Готовить он не будет. Он не даст",0,295,0,0],["v","Их укорять согражданам за праздность…",0,296,0,0],["v","И что еще? И ненависть толпы",0,297,0,0],["v","Они своим искусством не насытят.",0,298,0,0],["v","Ведь если ты невежд чему-нибудь,",0,299,0,0],["v","Хоть мудрому, но новому, обучишь,",0,300,0,1],["v","Готовься между них не мудрецом",0,300,0,0],["v","Прослыть, а тунеядцем. Пусть молвою",0,301,0,0],["v","Ты умников, которых город чтит,",0,302,0,0],["v","Поставлен хоть на палец выше будешь —",0,302,0,0],["v","Ты человек опасный. Эту участь",0,303,0,0],["v","Я тоже испытала. Чересчур",0,304,0,0],["v","Умна <span class=\"ch\" data-ch=\"medeya\">Медея</span> — этим ненавистна",0,305,0,0],["v","Она одним, другие же, как ты,",0,305,0,0],["v","Опасною ее считают дерзость.",0,306,0,0],["sd","Пауза."],["v","Подумаешь: покинутой жене",0,307,0,0],["v","Пугать царей?! Да и за что бы даже",0,307,0,0],["v","Тебе я зла хотела? Выдал дочь",0,308,0,0],["v","Ты, за кого желал: я ненавижу,",0,309,0,0],["v","Но не тебя, а мужа. Рассуждал",0,310,0,1],["v","Ты здраво, дочь сосватав, и твоей",0,310,0,0],["v","Удаче не завидую. Женитесь",0,311,0,0],["v","И наслаждайтесь жизнью, лишь меня",0,312,0,0],["v","Оставьте жить по-прежнему в Коринфе:",0,313,0,0],["v","Молчанием я свой позор покрою.",0,314,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Да, сладко ты поешь, но злая цель",0,315,0,0],["v","И в песнях нам мерещится: чем дольше",0,316,0,0],["v","Я слушаю, тем меньше убежден…",0,317,0,0],["v","Ведь от людей порыва остеречься",0,318,0,0],["v","Куда же легче нам, чем от таких,",0,319,0,0],["v","Как ты, жена, лукаво-осторожных.",0,320,0,1],["v","Ну, уходи! Все высказала ты,",0,320,0,0],["v","Но твоего искусства не хватает,",0,321,0,0],["v","Чтобы сберечь нам лишнего врага.",0,322,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["dir","с жестами мольбы, от которых <span class=\"ch\" data-ch=\"kreont\">Креонт</span> уклоняется"],["v","О, я молю у ног твоих — ты нас",0,323,0,0],["v","Не высылай, хоть ради новобрачных!",0,324,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Ты тратишься без толку на слова.",0,325,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","О, пощади… К мольбам моим склонися!",0,326,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Своя семья <span class=\"ch\" data-ch=\"medeya\">Медеи</span> ближе нам.",0,327,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","О, край родной! Ты ярко ожил в сердце…",0,328,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Милее нет и нам — после семьи.",0,329,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Какое зло вы сеете, Эроты!",0,330,0,1],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Ну, не всегда — зависит от судьбы.",0,330,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Виновному не дай укрыться, боже.",0,331,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["dir","в нетерпении"],["v","Не будет ли, однако? От себя",0,332,0,0],["v","И болтовни освободи нас лучше…",0,333,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Освободить?.. Кого и от чего?",0,334,0,0],["v","Ты вызволи нас, царь, из этой муки…",0,335,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["dir","несколько повышая тон"],["v","Ты, верно, ждешь расправы наших слуг?..",0,335,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","О нет, о нет, тебя я умоляю…",0,336,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["dir","не слушая ее"],["v","Угрозы мало, кажется, тебе?",0,337,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["dir","цепляясь за его плащ"],["v","Я не о том молю тебя, властитель.",0,338,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["v","Пусти меня… Чего ж тебе еще?..",0,339,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Дай день один мне сроку: не решила,",0,340,0,1],["v","Куда идти еще я, а детей",0,340,0,0],["v","Кто ж без меня устроит? Выше этих",0,341,0,0],["v","Забот <span class=\"ch\" data-ch=\"yason\">Ясон</span>.",0,342,0,0],["sd","(Видя, что <span class=\"ch\" data-ch=\"kreont\">Креонт</span> поддается.)"],["v","О, сжалься, царь, и ты",0,343,4,0],["v","Детей ласкал. Тебе знакомо чувство,",0,344,0,0],["v","Которое в нас будит слабый. Мне",0,345,0,0],["v","Изгнание не страшно… Если плачу,",0,346,0,0],["v","То лишь над их несчастием, <span class=\"ch\" data-ch=\"kreont\">Креонт</span>.",0,347,0,0],["sp","<span class=\"ch\" data-ch=\"kreont\">Креонт</span>"],["dir","мягче"],["v","Я не рожден тираном. Сколько раз",0,348,0,0],["v","Меня уже губила эта жалость.",0,349,0,0],["v","Вот и теперь я знаю, что не прав,",0,350,0,1],["v","Все ж будь по-твоему.",0,350,0,0],["sd","(Строго.)"],["v","Предупреждаю только,",0,351,4,0],["v","Что если здесь тебя с детьми и завтра",0,352,0,0],["v","В полях моих увидит солнце, смерть",0,353,0,0],["v","Оно твою осветит. Непреложно",0,354,0,0],["v","Да будет это слово… До утра…",0,355,0,0],["sd","(Уходит со свитою назад тем же путем.)"],["sp","Корифей"],["v","О, злая судьба!",0,356,0,0],["v","Увы, о жена, чт<em>о</em> бед-то, чт<em>о</em> бед!",0,357,0,0],["v","Куда ж ты пойдешь? У кого ты",0,358,0,0],["v","Приюта попросишь? Где дом",0,359,0,0],["v","И где та земля, Медея?",0,360,0,1],["v","В море бездонное зол",0,361,0,0],["v","Бросил тебя бессмертный.",0,362,0,0],["scene","Явление шестое","s7",2,7],["sd","Без <span class=\"ch\" data-ch=\"kreont\">Креонта</span>."],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["dir","тихо"],["v","О да! Темно на небе…",0,363,0,0],["v","Но на этом",1,363,0,0],["v","Не кончилось! Не думайте: еще",0,364,0,0],["v","И молодым счастливцам будет искус,",0,365,0,0],["v","И свату их довольно горя… Разве",0,366,0,0],["v","Ты думала, что сладкий этот яд",0,367,0,0],["v","Он даром пил, — все взвешено заране…",0,368,0,0],["v","Он с этих губ ни слова, он руки",0,370,0,1],["v","Единого движенья без расчета",0,370,0,0],["v","Не получил бы, верьте…",0,371,0,0],["v","О, слепец!..",1,371,0,0],["v","В руках держать решенье — и оставить",0,372,0,0],["v","На целый день…",0,373,0,0],["v","Довольно за глаза,",1,373,0,0],["v","Чтобы отца, и дочь, и мужа с нею",0,374,0,0],["v","Мы в трупы обратили… ненавистных…",0,375,0,0],["v","Немало есть и способов…",0,376,0,0],["v","Какой",1,376,0,0],["v","Я выберу, сама еще не знаю:",0,377,0,0],["v","Чертог поджечь невестин или медь",0,378,0,0],["v","Им острую должна вогнать я в печень…",0,379,0,0],["sd","Пауза."],["v","До ложа их добравшись?..",0,380,0,1],["v","Тут одна",1,380,0,0],["v","Смущает вероятность. По дороге",0,380,0,0],["v","До спальни их или за делом я",0,381,0,0],["v","Захвачена могу быть и злодеям",0,382,0,0],["v","Достаться на глумленье…",0,383,0,0],["v","Нет, уж лучше",1,383,0,0],["v","Не изменять пути прямому нам,",0,383,0,0],["v","И, благо он испытан, — яд на сцену…",0,384,0,0],["v","Так, решено…",0,385,0,0],["sd","Пауза."],["v","Ну, я убила их… А дальше что ж?",0,386,0,0],["v","Где город тот и друг, который двери",0,386,0,0],["v","Нам распахнет и, приютив, за нас",0,387,0,0],["v","Поручится?",0,388,0,0],["v","Такого нет… Терпенье ж",1,388,0,0],["v","Еще хоть ненадолго.",0,389,0,0],["v","Если стен",1,389,0,0],["v","Передо мной откроется защита,",0,390,0,1],["v","На тайную стезю убийства молча",0,390,0,0],["v","Ступлю тотчас.",0,391,0,0],["v","Но если нам одно",1,391,0,0],["v","Несчастье беспомощное на долю",0,392,0,0],["v","Останется, я меч беру открыто",0,393,0,0],["v","И дерзостно иду их убивать,",0,393,0,0],["v","Хотя бы смерть самой в глаза глядела.",0,394,0,0],["sd","(Со сдержанной страстью.)"],["v","Владычицей, которую я чту",0,395,0,0],["v","Особенно, пособницей моею,",0,396,0,0],["v","Родной очаг хранящею, клянусь",0,396,0,0],["v","Гекатою, что скорбию <span class=\"ch\" data-ch=\"medeya\">Медеи</span>",0,397,0,0],["v","Себе никто души не усладит!..",0,398,0,0],["v","Им горек пир покажется, а свату",0,399,0,0],["v","Его вино и слезы мук моих…",0,400,0,1],["v","За дело же! Медея, все искусство",0,400,0,0],["v","Ты призови на помощь, — каждый шаг",0,401,0,0],["v","Обдумать ты должна до мелочей!..",0,402,0,0],["v","Иди на самое ужасное! Ты, сердце,",0,403,0,0],["v","Теперь покажешь силу. До чего,",0,403,0,0],["v","О, до чего дошла ты! Неужели ж",0,404,0,0],["v","Сизифову потомству, заключив",0,405,0,0],["v","С <span class=\"ch\" data-ch=\"yason\">Ясоном</span> брак, позволишь надругаться",0,406,0,0],["v","Над Гелиевой кровью?",0,406,0,0],["v","Но кому<a class=\"nr\" href=\"#n-k12\" data-n=\"k12\" aria-label=\"Примечание 12\">12</a>",1,406,0,0],["v","Я говорю все это? Мы природой",0,407,0,0],["v","Так созданы — на доброе без рук,",0,408,0,0],["v","Да злым зато искусством всех мудрее…",0,409,0,0],["sd","(Хочет уйти в средние двери, но останавливается в раздумье, пока хор поет.)"],["scene","Первый музыкальный антракт","s8",2,8],["sp","Хор"],["str","Строфа I"],["v","Реки священные вспять потекли,",0,410,0,1],["v","Правда осталась, но та ли?",0,411,0,0],["v","Гордые выси коснулись земли,",0,412,0,0],["v","Имя богов попирая в пыли,",0,413,0,0],["v","Мужи коварными стали…",0,414,0,0],["v","Верно, и наша худая молва",0,415,1,0],["v","Тоже хвалой обратится,",0,416,1,0],["v","И полетят золотые слова",0,417,1,0],["v","Женам в усладу, что птица.",0,420,1,1],["str","Антистрофа I"],["v","Музы не будут мелодий венчать",0,421,0,0],["v","Скорбью о женском коварстве…<a class=\"nr\" href=\"#n-k13\" data-n=\"k13\" aria-label=\"Примечание 13\">13</a>",0,422,0,0],["v","Только бы с губ моих эту печать,",0,423,0,0],["v","Только б и женской цевнице звучать",0,424,0,0],["v","В розовом Фебовом царстве…",0,425,0,0],["v","О, для чего осудил Мусагет<a class=\"nr\" href=\"#n-k14\" data-n=\"k14\" aria-label=\"Примечание 14\">14</a>",0,426,0,0],["v","Песню нас слушать все ту же?",0,427,0,0],["v","В свитке скопилось за тысячи лет",0,428,0,0],["v","Мало ли правды о муже?",0,430,0,1],["str","Строфа II"],["v","О, бурное сердце менады!",0,430,0,0],["v","Из отчего дома, жена,<a class=\"nr\" href=\"#n-k15\" data-n=\"k15\" aria-label=\"Примечание 15\">15</a>",0,431,0,0],["v","Должно быть, пробив Симплегады,",0,432,0,0],["v","Несла тебя злая волна.",0,433,0,0],["v","Ты здесь на чужбине одна,",0,434,1,0],["v","Муж отдал тебя на терзанье;",0,435,1,0],["v","И срам и несчастье должна",0,435,1,0],["v","Влачить за собой ты в изгнанье.",0,436,1,0],["str","Антистрофа II"],["v","Священная клятва в пыли,",0,437,0,0],["v","Коварству нет больше предела,",0,438,0,0],["v","Стыдливость и та улетела",0,439,0,0],["v","На небо из славной земли.",0,440,0,1],["v","От бури спасти не могли",0,441,1,0],["v","Отцовские стрелы <span class=\"ch\" data-ch=\"medeya\">Медеи</span>,",0,442,1,0],["v","И руки царя увлекли",0,443,1,0],["v","Объятий ее горячее.",0,444,1,0],["act","Действие второе","a3","II"],["scene","Явление седьмое","s9",3,9],["sd","Справа приходит <span class=\"ch\" data-ch=\"yason\">Ясон</span>, нарядный, самоуверенный и веселый, в пурпуре, с ним небольшая свита. <span class=\"ch\" data-ch=\"yason\">Ясон</span> и <span class=\"ch\" data-ch=\"medeya\">Медея</span>."],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["sd","После немой сцены, когда на его приветствия <span class=\"ch\" data-ch=\"medeya\">Медея</span> не отвечает ни слова и молча отодвигается от него при его попытке подойти к ней, несколько секунд он смотрит на <span class=\"ch\" data-ch=\"medeya\">Медею</span>, которая, чтобы не видеть <span class=\"ch\" data-ch=\"yason\">Ясона</span>, закрыла лицо руками, потом —"],["v","Не в первый раз я вижу, сколько зол",0,445,0,0],["v","Влачит упорство злобы.",0,446,0,0],["v","Ты и город",1,446,0,0],["v","Могла б иметь, и дом теперь, царей",0,447,0,0],["v","Перенося смиренно волю. Если",0,448,0,0],["v","В изгнание идешь ты, свой язык",0,449,0,0],["v","Распущенный вини, жена.",0,450,0,1],["sd","Пауза."],["v","Конечно,",1,450,0,0],["v","Мне все равно — ты можешь повторять,",0,450,0,0],["v","Что низость тут виной моя; но меру",0,451,0,0],["v","Возмездия за то, что ты семье",0,452,0,0],["v","Властителя сулила, ты, Медея,",0,452,0,0],["v","Должна считать за благо.",0,453,0,0],["sd","Пауза. <span class=\"ch\" data-ch=\"medeya\">Медея</span> открывает лицо и слушает <span class=\"ch\" data-ch=\"yason\">Ясона</span>."],["v","Сколько мог,",1,453,0,0],["v","Я гнев царей удерживал, оставить",0,454,0,0],["v","Тебя просил я даже — ни к чему",0,455,0,0],["v","Все это было… У безумья вожжи",0,455,0,0],["v","Совсем ты распустила — злых речей",0,456,0,0],["v","Поток не умолкал, и город наш",0,457,0,0],["v","Тебе закрыт отныне.",0,457,0,0],["sd","(Стараясь говорить как можно нежнее.)"],["v","Но в заботах,",0,458,4,0],["v","Как верный друг, я устали не знаю.",0,459,0,0],["v","Я хлопочу о вас, чтобы нужды",0,460,0,1],["v","Не испытать жене моей и детям,",0,460,0,0],["v","Без денег не остаться. Мало ль зол",0,461,0,0],["v","Увидишь на чужбине…",0,462,0,0],["v","Ненавистен",1,462,0,0],["v","Тебе <span class=\"ch\" data-ch=\"yason\">Ясон</span>, но, право ж, не умеет",0,463,0,0],["v","На вражеский себя настроить лад.",0,464,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","О низкий… о негодный… я не знаю,",0,465,0,0],["v","Как выразить сильнее языком,",0,465,0,0],["v","Что ты не муж, не воин, — хуже, злее",0,466,0,0],["v","Нельзя уж быть, чем ты для нас, и к нам",0,467,0,0],["v","Ты все-таки приходишь… Тут не смелость…",0,468,0,0],["v","Отвага ли нужна, чтобы, друзьям",0,469,0,0],["v","Так навредив, в глаза смотреть? Иначе",0,470,0,1],["v","У нас зовут такой недуг — бесстыдство.",0,470,0,0],["v","Но все ж тебе я рада… сердце я",0,471,0,0],["v","Хоть облегчить могу теперь и болью",0,472,0,0],["v","Тебя донять… О, слушай… Как начну?",0,473,0,0],["v","Вот первое из первых… Я тебя",0,474,0,0],["v","Спасла — и сколько эллинов с собою",0,475,0,0],["v","На корабле везли тогда мы, все",0,475,0,0],["v","Свидетели тому, —",0,476,0,0],["v","спасла, когда ты",1,476,0,0],["v","Был послан укротить быков, огонь",0,477,0,0],["v","Метавших из ноздрей, и поле смерти",0,478,0,0],["v","Засеять. Это я дракона, телом",0,479,0,0],["v","Покрывшего в морщинистых извивах",0,480,0,1],["v","Руно златое, умертвила, я,",0,480,0,0],["v","Бессонного и зоркого, и солнца",0,481,0,0],["v","Сияние глазам твоим вернула.",0,482,0,0],["v","Сама ж, отца покинув, дом забыв,",0,483,0,0],["v","В Фессалию с тобой ушла, — горячка",0,484,0,0],["v","Была сильней рассудка. Пелий, царь,",0,485,0,0],["v","Убит был тоже <em>мною</em> — нет ужасней",0,486,0,0],["v","Той смерти, что нашел он — от детей!",0,487,0,0],["v","И все <em>тебя</em> я выручала, — этим",0,488,0,0],["v","От нас ты не побрезгал, а в награду",0,489,0,0],["v","Мне изменил.",0,490,0,1],["v","Детей моих отец,",1,490,0,0],["v","Ты брак затеял новый. Пусть бы семя",0,490,0,0],["v","Твое бесплодно было, жажду ложа",0,491,0,0],["v","Я поняла бы нового…",0,492,0,0],["v","А где ж?",1,492,0,0],["v","Где клятвы те священные? Иль боги,",0,493,0,0],["v","Которые внимали им, теперь",0,493,0,0],["v","Уж не царят, иль их законы новы?",0,494,0,0],["v","Ты сознаешь — нельзя не сознавать,",0,495,0,0],["v","Что клятву ты нарушил…",0,496,0,0],["v","Сколько раз",1,496,0,0],["v","Руки искал ты этой и колени",0,496,0,0],["v","Мне осквернял прикосновеньем! Все",0,497,0,0],["v","Обмануты надежды.",0,498,0,0],["v","Что же друга",1,498,0,0],["v","В тебе вернет <span class=\"ch\" data-ch=\"medeya\">Медее</span>, ждать чего ж",0,499,0,0],["v","Могла бы от тебя она? Но сердце",0,500,0,1],["v","Мне жжет еще уста — ясней позор",0,500,0,0],["v","Твой обличить вопросами…",0,501,0,0],["v","Итак,",1,501,0,0],["v","Куда же нам идти прикажешь? Или",0,502,0,0],["v","К отцу, домой? Тебе в угоду дом",0,502,0,0],["v","Я предала. К несчастным Пелиадам?",0,503,0,0],["v","У них отца убив, конечно, буду",0,504,0,0],["v","Я принята радушно. О друзьях",0,505,0,0],["v","Подумаю ли старых, — ненавистна",0,505,0,0],["v","Я стала им, а те, кому вредить",0,506,0,0],["v","Пришлося мне — не для себя — в угоду",0,507,0,0],["v","Тебе ж, Ясон, — теперь мои враги.",0,507,0,0],["v","О, горе мне! Так вот она, та слава,",0,508,0,0],["v","Блаженство то меж эллинов, что мне",0,509,0,0],["v","Тогда сулил ты лживо…",0,510,0,1],["v","Да, гордиться",1,510,0,0],["v","Могу я <em>верным</em> мужем, это так…",0,510,0,0],["v","И славою счастливый младожен",0,511,0,0],["v","Покроется не бледной, если, точно,",0,512,0,0],["v","Извергнута из города, одна",0,513,0,0],["v","И с беззащитными детьми, скитаясь,",0,514,0,0],["v","И с нищими та, чт<em>о</em> спасла его,",0,515,0,0],["v","Пойдет дивить людей своим несчастьем.",0,515,0,0],["v","О Зевс, о бог, коль ты для злата мог",0,516,0,0],["v","Поддельного открыть приметы людям,",0,517,0,0],["v","Так отчего ж не выжег ты клейма",0,518,0,0],["v","На подлеце, чтобы в глаза бросалось?..",0,519,0,0],["sp","Корифей"],["v","Неисцелим и страшен гнев встает,",0,520,0,1],["v","Когда вражда людей сшибает близких.",0,520,0,0],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["v","Кто не рожден оратором, тому",0,521,1,0],["v","Теперь беда. Как шкипер осторожный,",0,521,1,0],["v","Я опущу немножко паруса",0,522,1,0],["v","Надутые, иначе, право, буря",0,523,1,0],["v","Злоречия и эти вихри слов",0,523,1,0],["v","Потопят нас, жена.",0,524,1,0],["sd","(Подвигаясь к ней, интимно и язвительно.)"],["v","Свои услуги",0,525,4,0],["v","Ты в гордую сложила башню… Нет,",0,525,1,0],["v","Коль мой поход удачен, я Киприде",0,526,1,0],["v","Обязан тем, Киприде меж богов",0,526,1,0],["v","И меж людьми Киприде, — может быть,",0,527,1,0],["v","Та мысль иным и не по вкусу будет.",0,528,1,0],["v","Но оцени в ней тонкость: если кто",0,528,1,0],["v","Одушевлял <span class=\"ch\" data-ch=\"medeya\">Медею</span> на спасенье",0,529,1,0],["v","Ясоново, то был",0,530,1,1],["sd","(потихоньку)"],["v","Эрот… Зачем",0,531,4,0],["v","Рассматривать в деталях дело? Да,",0,532,1,0],["v","Я признаю твои услуги. Что же",0,533,1,0],["v","Из этого? Давно уплачен долг,",0,534,1,0],["v","И с лихвою. Во-первых, ты в Элладе",0,535,1,0],["v","И больше не меж варваров, закон",0,536,1,0],["v","Узнала ты и правду вместо силы,",0,537,1,0],["v","Которая царит у вас. Твое",0,538,1,0],["v","Здесь эллины искусство оценили,",0,539,1,0],["v","И ты имеешь славу, а живи",0,540,1,1],["v","Ты там, на грани мира, о тебе бы",0,540,1,0],["v","И не узнал никто.",0,541,1,0],["sd","(Мечтательно.)"],["v","Для нас ничто",0,542,4,0],["v","И золото в чертогах, и Орфея",0,542,1,0],["v","Нежнее песни голос, по сравненью",0,543,1,0],["v","С той славою, которая меня",0,544,1,0],["v","Так дивно увенчала.",0,545,1,0],["sd","(Возвращаясь к прежней сдержанности.)"],["v","О себе",0,545,4,0],["v","Упомянул я, впрочем, лишь затем,",0,546,1,0],["v","Что этот спор ты подняла. Отвечу",0,547,1,0],["v","По поводу женитьбы. Поступил,",0,547,1,0],["v","Во-первых, я умно, затем и скромно,",0,548,1,0],["v","И, наконец, на пользу и тебе,",0,549,1,0],["v","И нашим детям. Только ты дослушай.",0,550,1,1],["v","Когда из Иолка цепью за собою",0,550,1,0],["v","Сюда одни несчастия принес я,",0,551,1,0],["v","Изгнаннику какой удел счастливей",0,552,1,0],["v","Пригрезиться мог даже, чем союз",0,553,1,0],["v","С царевною?.. И ты напрасно колешь",0,553,1,0],["v","Нас тем, жена, что ненавистно ложе",0,554,1,0],["v","<span class=\"ch\" data-ch=\"medeya\">Медеи</span> мне, и новою сражен",0,555,1,0],["v","Я страстию, или детей хочу",0,556,1,0],["v","Иметь как можно больше… Я считаю,",0,556,1,0],["v","Что их у нас довольно, и тебя",0,557,1,0],["v","Мне упрекать тут не за что. Женился",0,558,1,0],["v","Я, чтоб себя устроить, чтоб нужды",0,559,1,0],["v","Не видеть нам — по опыту я знаю,",0,560,1,1],["v","Что бедного чуждается и друг.",0,561,1,0],["sd","(Стараясь придать голосу задушевность.)"],["v","Твоих же я хотел достойно рода",0,562,1,0],["v","Поднять детей, на счастие себе,",0,563,1,0],["v","Чрез братьев их, которые родятся.",0,564,1,0],["v","Зачем тебе еще детей? А мне",0,565,1,0],["v","Они нужны для пользы настоящих.",0,566,1,0],["v","Ну, будто ж я не прав?",0,567,1,0],["v","Сказала б «да»",1,567,0,0],["v","И ты, когда б не ревность.",0,568,1,0],["v","Все вы, жены,",1,568,0,0],["v","Считаете, что если ложа вам",0,569,1,0],["v","Не трогают, то все благополучно…",0,570,1,1],["v","А чуть беда коснулась спальни, нет",0,570,1,0],["v","Тут никому пощады; друг ваш лучший,",0,571,1,0],["v","Полезнейший совет — вам ненавистны.",0,572,1,0],["v","Нет, надо бы рождаться детям так,",0,573,1,0],["v","Чтоб не было при этом женщин, — люди",0,573,1,0],["v","Избавились бы тем от массы зол.",0,574,1,0],["sp","Корифей"],["v","Ты речь, Ясон, украсил, но сдается<a class=\"nr\" href=\"#n-k16\" data-n=\"k16\" aria-label=\"Примечание 16\">16</a>",0,575,0,0],["v","Мне все-таки, меня не обессудь,",0,576,0,0],["v","Что ты не прав, <span class=\"ch\" data-ch=\"medeya\">Медею</span> покидая.",0,576,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","О, я во многом, верно, от людей",0,577,0,0],["v","И многих отличаюсь. Наказанью",0,578,0,0],["v","Я высшему подвергла бы того,",0,579,0,0],["v","Кто говорить умеет, коль при этом",0,580,0,1],["v","Он оскорбляет правду.",0,580,0,0],["v","Языком",1,580,0,0],["v","Искусным величаясь, человек",0,581,0,0],["v","Такой всегда оденет зло прилично…",0,582,0,0],["v","Под маской же на что он не дерзнет?",0,583,0,0],["v","Но есть изъян и в мудрости, увы!..",0,583,0,0],["v","Ты, например, и тонкою и хитрой",0,584,0,0],["v","Раскинул сетью речь, а поразить",0,585,0,0],["v","Нам ничего тебя не стоит. Честный",0,586,0,0],["v","Уговорил бы близких и потом",0,586,0,0],["v","Вступал бы в брак, а ты сперва женился…",0,587,0,0],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["dir","задетый"],["v","Скажи тебе заранее, сейчас",0,588,0,0],["v","Ты так бы и послушалась, — ты злобу",0,589,0,0],["v","И до сих пор на сердце бережешь.",0,590,0,1],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["dir","не спуская с него глаз, раздельно"],["v","Другого ты боялся, чтоб женатым",0,590,0,0],["v","На варварской царевне не остаться:<a class=\"nr\" href=\"#n-k17\" data-n=\"k17\" aria-label=\"Примечание 17\">17</a>",0,591,0,0],["v","Вам, эллинам, под старость это тяжко.",0,592,0,0],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["dir","быстро и несколько смущенно"],["v","Пожалуйста, не думай, что жена",0,593,0,0],["v","При чем-нибудь в моем союзе новом;",0,594,0,0],["v","Я говорил уже, что я тебя",0,595,0,0],["v","Спасти хотел, родив единокровных",0,595,0,0],["v","Твоим сынам царей, опору дома.",0,596,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Нам счастия не надо, что ценой",0,597,0,0],["v","Такой обиды куплено; богатства,",0,598,0,0],["v","Терзающего сердце, не хочу.",0,599,0,0],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["dir","наставительно"],["v","Моли богов, желания иные",0,600,0,1],["v","Влагая в грудь <span class=\"ch\" data-ch=\"medeya\">Медее</span>, умудрить",0,600,0,0],["v","Ее, чтоб ей полезное — обидой",0,601,0,0],["v","И счастие не грезилось несчастьем…",0,602,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Глумись… тебе приюта не искать.",0,603,0,0],["v","Изгнанница пред вами беззащитна.",0,604,0,0],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["v","Твой выбор был — других и не вини.",0,605,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["dir","с живостью"],["v","Так это я женилась, изменяла?",0,605,0,0],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["v","Безбожно ты кляла своих царей.",0,606,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","И твоему проклятьем дому буду.",0,607,0,0],["sd","Пауза."],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["dir","сухо"],["v","На этом мы и кончим. Если вам —",0,608,0,0],["v","Тебе иль детям нашим — деньги нужны",0,609,0,0],["v","Ввиду пути, прошу сказать теперь;",0,610,0,1],["v","Отказа вам не будет. Я и знаки",0,610,0,0],["v","Гостиные могу послать друзьям,",0,611,0,0],["v","Помогут вам…",0,612,0,0],["sd","(На отрицательный жест <span class=\"ch\" data-ch=\"medeya\">Медеи</span>.)"],["v","Не хочешь брать? Напрасно.<a class=\"nr\" href=\"#n-k18\" data-n=\"k18\" aria-label=\"Примечание 18\">18</a>",0,613,4,0],["v","Открой глаза, не гневайся, тебе ж —",0,614,0,0],["v","О женщина, поверь — полезней будет.",0,615,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Твоих друзей не надо нам, и денег",0,616,0,0],["v","Я не возьму — не предлагай, — от мужа",0,617,0,0],["v","Бесчестного подарок руки жжет.",0,618,0,0],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["dir","поднимая глаза к небу"],["v","Богов беру в свидетели, что пользы",0,619,0,0],["v","Я всячески и детской и твоей",0,620,0,1],["v","Искал, жена, но доброты не ценит",0,621,0,0],["v","Надменная моей, — и ей же хуже.",0,622,0,0],["sd","(Делает знак свите и, не глядя на <span class=\"ch\" data-ch=\"medeya\">Медею</span>, быстро уходит в ту же сторону, откуда пришел.)"],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["dir","вслед ему"],["v","Ступай. Давно по молодой жене",0,623,1,0],["v","Душа горит — чертог тебя заждался.",0,624,1,0],["v","Что ж? Празднуй брак! Но слово скажет бог:",0,625,1,0],["v","Откажешься, жених, и от невесты.",0,626,1,0],["sd","(Остается на сцене, погруженная в думы.)"],["scene","Второй музыкальный антракт","s10",3,10],["sp","Хор"],["str","Строфа I"],["v","Когда свирепы Эроты,",0,627,0,0],["v","Из сердца они уносят",0,628,0,0],["v","Всю сладость и славы людям",0,629,0,0],["v","Вкусить не дают. Но если",0,630,0,1],["v","Киприда шлет только радость,",0,631,0,0],["v","Нет богини прелестней…",0,632,0,0],["v","Ты мне никогда, царица,",0,633,0,0],["v","Стрел не мечи золотых",0,634,0,0],["v","И неизбежных в сердце,",0,635,0,0],["v","Полных яда желаний.",0,636,0,0],["str","Антистрофа I"],["v","Скромной ласки хочу я:",0,637,0,0],["v","Нет дара бессмертных слаще.",0,638,0,0],["v","О, пусть никогда Киприды",0,639,0,0],["v","Ужасной не слышу в сердце,",0,640,0,1],["v","С грозой ее ярых ударов,",0,640,0,0],["v","С бурей ссор ненавистной,",0,641,0,0],["v","С желаньем чужого ложа!",0,642,0,0],["v","Спальню, где нет войны,",0,643,0,0],["v","Ложе, где жены не спорят,",0,643,0,0],["v","Славить гимном хочу я.",0,644,0,0],["str","Строфа II"],["v","Родина, дом отцовский, о, пусть,",0,645,0,0],["v","Пусть никогда не стану",0,646,0,0],["v","Города я лишенной…",0,646,0,0],["v","Злее нет горя в жизни",0,647,0,0],["v","Дней беспомощных.",0,648,0,0],["v","Смерти, о, смерти пускай",0,649,0,0],["v","Иго подъемлю, но только",0,650,0,1],["v","Дня изгнанья не видеть…",0,651,0,0],["v","Муки нет тяжелее,",0,652,0,0],["v","Чем отчизны лишиться.<a class=\"nr\" href=\"#n-k19\" data-n=\"k19\" aria-label=\"Примечание 19\">19</a>",0,653,0,0],["str","Антистрофа II"],["v","Вижу сама — не люди, увы,",0,654,0,0],["v","Сказку сложили эту!..",0,655,0,0],["v","Города ты лишилась,",0,656,0,0],["v","Друг состраданьем муки",0,657,0,0],["v","Не облегчает,",0,658,0,0],["v","Неблагодарный… Пускай",0,659,0,0],["v","Сгибнет, коль друга не чтит он.",0,660,0,1],["v","Сердце чистое должен",0,660,0,0],["v","Он открыть ему, сердце:",0,661,0,0],["v","Друга иного не надо.",0,662,0,0],["act","Действие третье","a4","III"],["scene","Явление восьмое","s11",4,11],["sd","Со стороны моря приходит <span class=\"ch\" data-ch=\"egey\">Эгей</span> со свитой. Одет по-дорожному, но в лаврах. <span class=\"ch\" data-ch=\"egey\">Эгей</span> и <span class=\"ch\" data-ch=\"medeya\">Медея</span>."],["sp","<span class=\"ch\" data-ch=\"egey\">Эгей</span>"],["v","О, радуйся, Медея! Я люблю",0,663,0,0],["v","Приветствовать друзей таким желаньем.",0,664,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Привет тебе, о Пандиона сын<a class=\"nr\" href=\"#n-k20\" data-n=\"k20\" aria-label=\"Примечание 20\">20</a>",0,665,0,0],["v","Премудрого, Эгей! Откуда к нам?",0,666,0,0],["sp","<span class=\"ch\" data-ch=\"egey\">Эгей</span>"],["v","Я навещал оракул Феба древний.",0,667,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Зачем тебе был серединный храм?<a class=\"nr\" href=\"#n-k21\" data-n=\"k21\" aria-label=\"Примечание 21\">21</a>",0,668,0,0],["sp","<span class=\"ch\" data-ch=\"egey\">Эгей</span>"],["v","Детей иметь хотел бы я, <span class=\"ch\" data-ch=\"medeya\">Медея</span>.",0,669,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Ты до сих пор бездетен, боже мой!",0,670,0,1],["sp","<span class=\"ch\" data-ch=\"egey\">Эгей</span>"],["v","То демона какого-то желанье.",0,671,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Но ты женат или не ведал ложа?",0,672,0,0],["sp","<span class=\"ch\" data-ch=\"egey\">Эгей</span>"],["v","От брачного ярма я не ушел.",0,673,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","И что ж тебе поведал бог о детях?",0,674,0,0],["sp","<span class=\"ch\" data-ch=\"egey\">Эгей</span>"],["v","Увы! Его не понимаю слов.",0,675,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Услышать их могла ль бы я?",0,676,0,0],["sp","<span class=\"ch\" data-ch=\"egey\">Эгей</span>"],["v","Еще бы.",1,676,0,0],["v","Тут именно и нужен тонкий ум.",0,677,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Так передай их нам, коль не зазорно.",0,678,0,0],["sp","<span class=\"ch\" data-ch=\"egey\">Эгей</span>"],["v","Мол, «из мешка ноги не выпускай».",0,679,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Пока чего не сделаешь? Иль в землю",0,680,0,1],["v","Какую не придешь? Должно быть, так?",0,680,0,0],["sp","<span class=\"ch\" data-ch=\"egey\">Эгей</span>"],["v","В отцовский дом покуда не вернешься.",0,681,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","А ты сюда-то прибыл для чего ж?",0,682,0,0],["sp","<span class=\"ch\" data-ch=\"egey\">Эгей</span>"],["v","Нам нужен царь Питфей земли трезенской.",0,683,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Сын набожный Пелопов, так ли, царь?",0,683,0,0],["sp","<span class=\"ch\" data-ch=\"egey\">Эгей</span>"],["v","Я сообщить ему хочу оракул.<a class=\"nr\" href=\"#n-k22\" data-n=\"k22\" aria-label=\"Примечание 22\">22</a>",0,684,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Да, мудрый муж — в оракулах силен.",0,685,0,0],["sp","<span class=\"ch\" data-ch=\"egey\">Эгей</span>"],["v","А мне к тому ж он и соратник близкий.",0,686,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Дай бог тебе и счастия, Эгей,",0,686,0,0],["v","И всех твоих желаний исполненья.",0,687,0,0],["sp","<span class=\"ch\" data-ch=\"egey\">Эгей</span>"],["dir","разглядывая <span class=\"ch\" data-ch=\"medeya\">Медею</span>"],["v","Ты ж отчего, скажи, Медея, так",0,688,0,0],["v","Осунулась в лице, глаза потухли?",0,689,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Муж у меня последний из людей.",0,690,0,1],["sp","<span class=\"ch\" data-ch=\"egey\">Эгей</span>"],["v","Скажи ясней причину огорченья.",0,691,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Оскорблена я им — и ни за что…",0,692,0,0],["sp","<span class=\"ch\" data-ch=\"egey\">Эгей</span>"],["v","Да сделал что ж <span class=\"ch\" data-ch=\"yason\">Ясон</span>? Скажи мне прямо.",0,693,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Взял женщину — хозяйку надо мной.",0,694,0,0],["sp","<span class=\"ch\" data-ch=\"egey\">Эгей</span>"],["v","Он не посмел бы, нет. Постыдно слишком.",0,695,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Вот именно он так и поступил.",0,696,0,0],["sp","<span class=\"ch\" data-ch=\"egey\">Эгей</span>"],["v","Влюбился, что ль, или ты ему постыла?",0,697,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Должно быть, страсть, — измена ж налицо.",0,698,0,0],["sp","<span class=\"ch\" data-ch=\"egey\">Эгей</span>"],["v","Так бог же с ним, коль сердцем он так низок.",0,699,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","К царевне он присватался, <span class=\"ch\" data-ch=\"egey\">Эгей</span>.",0,700,0,1],["sp","<span class=\"ch\" data-ch=\"egey\">Эгей</span>"],["v","А у кого? Хотел бы я дослушать.",0,700,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Коринфский царь <span class=\"ch\" data-ch=\"kreont\">Креонт</span> — ее отец.",0,701,0,0],["sp","<span class=\"ch\" data-ch=\"egey\">Эгей</span>"],["v","Вот отчего ты к сердцу принимаешь.",0,702,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","И мужа нет, и гонят — все зараз.",0,703,0,0],["sp","<span class=\"ch\" data-ch=\"egey\">Эгей</span>"],["v","То новое несчастие — откуда ж?",0,704,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Все от того ж коринфского царя.",0,705,0,0],["sp","<span class=\"ch\" data-ch=\"egey\">Эгей</span>"],["v","С согласия <span class=\"ch\" data-ch=\"yason\">Ясона</span>? Что за низость!",0,705,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Послушаешь его, так нет: <span class=\"ch\" data-ch=\"yason\">Ясон</span>",0,706,0,0],["v","Желание свое по принужденью",0,707,0,0],["v","Чужому исполняет.",0,708,0,0],["sd","(С движениями молящей.)"],["v","Но, Эгей,",0,709,4,0],["v","Ланитою и святостью колен",0,710,0,1],["v","Тебя молю: о, сжалься над несчастной",0,711,0,0],["v","Изгнанницей покинутой, прими",0,712,0,0],["v","Ее в страну, ей угол дай. За это",0,713,0,0],["v","Тебе детей желанных ниспошлют",0,714,0,0],["v","Бессмертные и славную кончину.",0,715,0,0],["v","Ты каяться не будешь, и, поверь,",0,716,0,0],["v","Ты не умрешь бездетным. Знаю средства",0,717,0,0],["v","Я верные, чтобы отцом ты стал.",0,718,0,0],["sp","<span class=\"ch\" data-ch=\"egey\">Эгей</span>"],["dir","поднимая ее"],["v","Тебе помочь хочу, ради бессмертных,",0,719,0,0],["v","Жена, и это главное, но нам",0,720,0,1],["v","Заманчиво и обещанье сделать",0,720,0,0],["v","Меня отцом. Я весь ушел душой",0,721,0,0],["v","В желанье это, им я весь захвачен.",0,722,0,0],["v","А для тебя я постараюсь быть",0,723,0,0],["v","Хозяином радушным; брать с собою",0,724,0,0],["v","Тебя, пожалуй, было б не с руки;",0,725,0,0],["v","Но если ты сама придешь в Афины,",0,726,0,0],["v","Я дам тебе приют и никому",0,727,0,0],["v","Тебя не выдам — можешь быть покойна.",0,728,0,0],["v","Но этот край покинешь ты без нас.",0,729,0,0],["v","Рассориться с друзьями не желал бы",0,730,0,1],["v","Из-за тебя я — прямо говорю.",0,730,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Пусть так оно и будет. Но поруки",0,731,0,0],["v","Ты не дал нам. Могу ль покойна быть?",0,732,0,0],["sp","<span class=\"ch\" data-ch=\"egey\">Эгей</span>"],["v","Так разве мне не веришь ты, Медея?",0,733,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Я верю, да. Но у меня враги:",0,733,0,0],["v","В Фессалии и здешний царь. И если",0,734,0,0],["v","Ты будешь связан клятвой, в руки к ним",0,735,0,0],["v","Не попаду, я знаю, а без клятвы,",0,736,0,0],["v","Лишь посулив спасенье, разве ты,",0,736,0,0],["v","Их осажден герольдами и дружбой",0,737,0,0],["v","Подвинутый, не можешь под конец",0,738,0,0],["v","И уступить? Я тоже друг, положим,",0,739,0,0],["v","Но слабый друг, а против нас — цари.",0,740,0,1],["sp","<span class=\"ch\" data-ch=\"egey\">Эгей</span>"],["dir","после некоторого раздумья, с тем же благодушным спокойствием"],["v","Ты, кажется, уж слишком дальновидна.",0,740,0,0],["v","Но, если так тебе душа велит,",0,741,0,0],["v","Отказа нет тебе от нас и в этом.",0,742,0,0],["v","Да, может быть, и нам всего верней",0,742,0,0],["v","Перед твоим врагом сослаться будет",0,743,0,0],["v","На то, что мы клялись… Тебе ж — залог…",0,744,0,0],["v","Ну, называй богов, какими клясться.",0,745,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Клянись Земли широким лоном, Солнцем,",0,745,0,0],["v","Отцом отца <span class=\"ch\" data-ch=\"medeya\">Медеи</span> и богами…",0,746,0,0],["v","Всем родом ты божественным клянись.",0,747,0,0],["sp","<span class=\"ch\" data-ch=\"egey\">Эгей</span>"],["v","Что сделаю или чего, жена,",0,747,0,0],["v","Не сделаю, сказать я, верно, должен?",0,748,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Что сам <span class=\"ch\" data-ch=\"medeya\">Медеи</span> не изгонишь, если ж",0,749,0,0],["v","Кто из врагов потребует меня,",0,750,0,1],["v","Покуда жив — и волею не выдашь.",0,750,0,0],["sp","<span class=\"ch\" data-ch=\"egey\">Эгей</span>"],["dir","поднимая руку"],["v","Святынею Земли и Солнца, всеми",0,751,0,0],["v","Богами я клянусь не изменить.",0,752,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Так хорошо, а если ты изменишь…",0,753,0,0],["sp","<span class=\"ch\" data-ch=\"egey\">Эгей</span>"],["v","С безбожником да разделю конец.",0,754,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["dir","радостно, поднимая руки к небу"],["v","Ну, в добрый час, Эгей, и добрый путь!",0,755,0,0],["v","Я — следом за тобою, — только раньше",0,756,0,0],["v","Готовое на свет явлю, и пусть",0,757,0,0],["v","Желанное свершит судьба <span class=\"ch\" data-ch=\"medeya\">Медее</span>.",0,758,0,0],["sd","<span class=\"ch\" data-ch=\"egey\">Эгей</span> уходит в ту сторону, откуда пришел. Хор провожает его стихами."],["sp","Хор"],["v","Сын Майи, божественный вождь,<a class=\"nr\" href=\"#n-k23\" data-n=\"k23\" aria-label=\"Примечание 23\">23</a>",0,759,0,0],["v","Да к дому приблизит <span class=\"ch\" data-ch=\"egey\">Эгея</span>!",0,760,0,1],["v","И все, что задумал ты, царь,",0,761,0,0],["v","Пускай совершится скорее.",0,762,0,0],["v","Рожденья высокого знак",0,763,0,0],["v","Ты в сердце зажег восхищенном…",0,764,0,0],["scene","Явление девятое","s12",4,12],["sd","<span class=\"ch\" data-ch=\"medeya\">Медея</span> и хор."],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","О, Зевс! О, правда Зевса! Солнца свет!",0,765,0,0],["v","Победой мы украсимся, подруги,",0,766,0,0],["v","Победою. Я знаю наконец,<a class=\"nr\" href=\"#n-k24\" data-n=\"k24\" aria-label=\"Примечание 24\">24</a>",0,767,0,0],["v","Куда мне плыть. И гавань перед нами",0,768,0,0],["v","Желанная открылась. Стоит нам",0,770,0,1],["v","Туда канат закинуть, и Паллады",0,771,0,0],["v","Нас примет славный город. А теперь",0,772,0,0],["v","Решение узнай мое, не думай,",0,773,0,0],["v","Что я шучу, пожалуйста. Сюда",0,774,0,0],["v","Рабыня к нам потребует <span class=\"ch\" data-ch=\"yason\">Ясона</span>",0,775,0,0],["v","От имени <span class=\"ch\" data-ch=\"medeya\">Медеи</span>. Он найдет",0,776,0,0],["v","Здесь ласковый прием и убедится,",0,777,0,0],["v","Что я на все согласна и что мил",0,778,0,0],["v","Нам приговор <span class=\"ch\" data-ch=\"kreont\">Креонта</span>. Лишь о детях",0,779,0,0],["v","Его молить я буду, чтобы их",0,780,0,1],["v","Оставили в Коринфе. Не затем",0,780,0,0],["v","Я этого хочу, чтоб меж врагами",0,781,0,0],["v","Оставить их, — но мне убить царевну",0,782,0,0],["v","Они помогут хитростью, чрез них",0,783,0,0],["v","Я перешлю дары ей: пеплос дивный",0,784,0,0],["v","И золотую диадему. Тот",0,785,0,0],["v","Чарующий едва она наденет",0,786,0,0],["v","Убор, погибнет в муках, — кто бы к ней",0,787,0,0],["v","Потом ни прикоснулся — тоже ядом",0,788,0,0],["v","Я напою дары свои, жена.",0,789,0,0],["v","Об этом слов довольно…",0,790,0,1],["v","Но, стеная,",1,790,0,0],["v","Я передам теперь, какое зло",0,790,0,0],["v","Глядит в глаза <span class=\"ch\" data-ch=\"medeya\">Медее</span> после… Я",0,791,0,0],["v","Должна убить детей.",0,792,0,0],["v","И их не вырвет",1,792,0,0],["v","У нас никто. Сама <span class=\"ch\" data-ch=\"yason\">Ясонов</span> с корнем",0,792,0,0],["v","Я вырву дом. А там — пускай ярмо",0,793,0,0],["v","Изгнания, клеймо детоубийцы,",0,794,0,0],["v","Безбожия позор, — все, что хотите.",0,795,0,0],["v","Я знаю, что врага не насмешу,",0,795,0,0],["v","А дальше все погибни…",0,796,0,0],["v","Точно, в жизни",1,796,0,0],["v","Чего жалеть бы стала я? Отчизны?<a class=\"nr\" href=\"#n-k25\" data-n=\"k25\" aria-label=\"Примечание 25\">25</a>",0,797,0,0],["v","Родительского крова? Ведь угла,",0,797,0,0],["v","Угла, где схоронить мои несчастья,",0,798,0,0],["v","Нет у меня на свете. О, зачем",0,799,0,0],["v","Я верила обманам, покидая",0,800,0,1],["v","Отцовский дом, и эллину себя",0,800,0,0],["v","Уговорить позволила? А впрочем,",0,801,0,0],["v","Мы с помощью богов свое возьмем",0,802,0,0],["v","С предателя. И никогда рожденных",0,802,0,0],["v","<span class=\"ch\" data-ch=\"medeya\">Медеею</span> себе на радость он",0,803,0,0],["v","Не обольет лучами глаз, невеста ж",0,804,0,0],["v","Желанная других не принесет.",0,804,0,0],["v","Ей суждены, порочной, только муки",0,805,0,0],["v","От чар моих и в муках — злая смерть.",0,806,0,0],["v","Ни слабою, ни жалкою, наверно,",0,806,0,0],["v","В устах людей я не останусь; нас",0,807,0,0],["v","Не назовут и терпеливой; нрава",0,808,0,0],["v","Иного я: на злобу я двумя,",0,808,0,0],["v","А на любовь двойною отвечаю.",0,809,0,0],["v","Все в мире дети славы таковы.",0,810,0,1],["sp","Корифей"],["v","Посвящена в твой замысел и только",0,810,0,0],["v","Добра тебе желая, не могу",0,811,0,0],["v","Я все ж забыть о Правде, — солнце миру, —",0,812,0,0],["v","И говорю тебе одно — оставь.",0,812,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["dir","подумав"],["v","Мне поступить нельзя иначе. Муки ж",0,813,0,0],["v","Не испытав моей, тебе, жена,",0,814,0,0],["v","Понять мои желанья тоже трудно.",0,815,0,0],["sp","Корифей"],["v","И ты убьешь детей, решишься ты?",0,815,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Чем уязвить могу больней <span class=\"ch\" data-ch=\"yason\">Ясона</span>?",0,816,0,0],["sp","Корифей"],["v","Несчастием еще ль ты не сыта?",0,817,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Пусть гибнет все… А вы, уста чужие,",0,817,0,0],["v","Свое уже сказали.",0,818,0,0],["sd","(Одной из рабынь.)"],["v","Ты ступай",0,819,4,0],["v","И приведи <span class=\"ch\" data-ch=\"yason\">Ясона</span> к нам; коль верной",0,820,0,1],["v","Потребует судьба у нас слуги,",0,820,0,0],["v","Кого назвать другого? Ничего",0,821,0,0],["v","Не говори ему о наших планах.",0,822,0,0],["v","Но госпожу ты любишь, и сама",0,823,0,0],["v","Ты женщина. Нас, верно, поняла ты.",0,824,0,0],["sd","Рабыня с поклоном уходит направо, по дороге. <span class=\"ch\" data-ch=\"medeya\">Медея</span> с загадочной улыбкой делает несколько шагов к средней двери и, дав знак рабыням следовать за собою, входит в дом."],["scene","Третий музыкальный антракт","s13",4,13],["sp","Хор"],["str","Строфа I"],["v","О Эрехтиды древле блаженные,",0,825,0,0],["v","Дети блаженных богов!",0,826,0,0],["v","Меж недоступных хранят вас холмов",0,827,0,0],["v","Нивы священные.",0,828,0,0],["v","Там славы жар вам в жилы влит,",0,829,0,0],["v","Там нега в воздухе разлита,",0,830,0,1],["v","Там девять чистых Пиэрид",0,831,0,0],["v","Златой Гармонией повиты.",0,832,0,0],["str","Антистрофа I"],["v","Дивной Киприды прикосновение",0,833,0,0],["v","Струи Кефиса златит,",0,834,0,0],["v","Ласково следом по нивам летит",0,835,0,0],["v","Роз дуновение.",0,836,0,0],["v","Благоухая в волосах,",0,837,0,0],["v","Цветы не вянут там свитые,",0,840,0,1],["v","И у рассудка золотые",0,841,0,0],["v","Всегда Эроты на часах…",0,842,0,0],["sd","<span class=\"ch\" data-ch=\"medeya\">Медея</span> выходит из дому старательней причесанная и одетая, с видом более нежным и женственным. За ней — рабыни."],["str","Строфа II"],["v","Тебя ж те чистые волны,",0,843,0,0],["v","И город, и друг,",0,844,0,0],["v","Скажи мне, принять<a class=\"nr\" href=\"#n-k26\" data-n=\"k26\" aria-label=\"Примечание 26\">26</a>",0,845,0,0],["v","Решатся ли, если",0,846,0,0],["v","Детей ты погубишь?",0,850,0,1],["v","Представь себе только",0,850,0,0],["v","Весь этот ужас…",0,851,0,0],["v","Раны на детях!..",0,852,0,0],["v","Видишь, твои",0,852,0,0],["v","Я обняла",0,853,0,0],["v","В мольбе колена…",0,854,0,0],["sd","<span class=\"ch\" data-ch=\"medeya\">Медея</span> молча ломает руки. Глаза ее сохраняют странное светлое выражение."],["v","О, пощади,",0,855,0,0],["v","Не убивай,",0,855,0,0],["v","Медея, милых.",0,856,0,0],["str","Антистрофа II"],["v","Откуда же дерзость рука",0,857,0,0],["v","И сердце возьмут,",0,857,0,0],["v","Скажи мне, скажи,",0,858,0,0],["v","Зарезать малюток?",0,859,0,0],["v","Лучи, упадая",0,860,0,1],["v","Из глаз на дрожащих,",0,860,0,0],["v","Выжгут ли слез",0,861,0,0],["v","Детскую долю?",0,862,0,0],["v","Нет, никогда",0,862,0,0],["v","Руку в крови",0,863,0,0],["v","Детей молящих",0,864,0,0],["v","Ты не дерзнешь",0,865,0,0],["v","Свою смочить",0,865,0,0],["v","В гневе безбожном.",0,866,0,0],["sd","Во время пения последних стихов вбегает рабыня, знаками останавливая хор."],["act","Действие четвертое","a5","IV"],["scene","Явление десятое","s14",5,14],["sd","Те же и <span class=\"ch\" data-ch=\"yason\">Ясон</span> из правого прохода, со свитой. <span class=\"ch\" data-ch=\"yason\">Ясон</span>, <span class=\"ch\" data-ch=\"medeya\">Медея</span> и хор."],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["v","Я приглашен… и хоть враждебно ты",0,867,0,0],["v","Настроена, но выслушать хотел бы",0,867,0,0],["v","Желания, о женщина, твои.",0,868,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["dir","начинает тихим, почти нежным голосом и по временам опуская глаза, но скрытая злоба скоро начинает давать себя знать, и голос <span class=\"ch\" data-ch=\"medeya\">Медеи</span> сливается с принятым ею на себя смиренным тоном"],["v","Прощения за то, что здесь ты слышал,",0,869,0,0],["v","Я у тебя прошу, Ясон, — любовь",0,870,0,1],["v","Жила меж нас так долго,",0,870,0,0],["sd","(с искусственно подавленным вздохом)"],["v","что горячность",0,871,4,0],["v","Мою поймешь ты, верно. Я же, царь,",0,872,0,0],["v","Додумалась до горького упрека",0,872,0,0],["v","Самой себе.",0,873,0,0],["v","Безбожница, чего ж",1,873,0,0],["v","Беснуюсь я, и в самом деле злобой",0,874,0,0],["v","На дружбу отвечая, на властей",0,874,0,0],["v","И мужа поднимаясь? Если даже",0,875,0,0],["v","Женился муж на дочери царя",0,876,0,0],["v","И для детей моих готовит братьев,",0,876,0,0],["v","Так я должна же помнить, что для нас",0,877,0,0],["v","Он это делает…",0,878,0,0],["v","Неужто гнев",1,878,0,0],["v","Так дорог сердцу? Что с тобой, Медея?",0,878,0,0],["v","Да разве все не к лучшему? Иль нет",0,879,0,0],["v","Детей у нас, а есть отчизна, город?",0,880,0,1],["v","Иль все мы не изгнанники, друзей",0,880,0,0],["v","Лишенные?..",0,881,0,0],["v","Легкая пауза, у <span class=\"ch\" data-ch=\"medeya\">Медеи</span> сорвался голос.",0,882,0,0],["v","Все это обсудивши,",0,882,4,0],["v","Я поняла, что было не умно",0,883,0,0],["v","Сердиться и напрасно. Я тебя",0,884,0,0],["v","Хвалю теперь… И точно, долг и скромность",0,885,0,0],["v","Тобою управляли, о Ясон,",0,885,0,0],["v","Когда ты брак задумал новый; жалко,",0,886,0,0],["v","Самой тогда на ум мне не пришло",0,887,0,0],["v","Войти в твой план советом…",0,887,0,0],["v","и невесте",1,887,0,0],["v","Прислуживать твоей, гордясь таким",0,888,0,0],["v","Родством… увы!",0,889,0,0],["v","Но что же делать? Все мы",1,889,0,0],["v","Такие женщины — будь не в обиду вам.",0,890,0,1],["sd","(К хору.)"],["v","Но ты, Ясон, не станешь слабым женам",0,890,0,0],["v","Подобиться, не будешь отвечать",0,891,0,0],["v","Ребячеством на женскую наивность…",0,892,0,0],["v","Я рассуждала плохо, но мои",0,892,0,0],["v","Решения переменились…",0,893,0,0],["sd","(Обращается к дому и зовет.)"],["v","Гей!",0,894,4,0],["sd","Из дому — дети. <span class=\"ch\" data-ch=\"medeya\">Медея</span> идет к ним навстречу: они сначала недоверчиво подходят к ней, но, видя ее ласковое движение, берут ее протянутую руку, хотя все еще не без некоторого колебания."],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["dir","наклоняясь к детям"],["v","О дети милые!",0,895,0,0],["v","Вы обнимите крепче",1,895,0,0],["v","Отца и вслед за мною повторяйте",0,895,0,0],["v","С приветом и любовью, что беречь",0,896,0,0],["v","На друга зла не будем…",0,897,0,0],["v","Восстановлен",0,897,0,0],["v","Мир, гнев — забыт.",1,897,0,0],["v","Держитесь, дети, так,",0,898,0,0],["v","Вот вам моя рука… О, горе, горе!",0,899,0,0],["v","Над вами туча, дети… а за ней?",0,900,0,1],["v","И долго ли вам жить еще, а мне",0,900,0,0],["v","Глядеть на ваши руки, что во мне",0,901,0,0],["v","Защиты ищут…",0,901,0,0],["v","Жалкая душа!",1,901,0,0],["v","Ты, кажется, готова плакать, дрожью",0,902,0,0],["v","Объята ты.",0,903,0,0],["sd","(Пауза. Потом сквозь слезы.)"],["v","Да, так давно с отцом",0,903,4,0],["v","Была я в ссоре вашим, и теперь,",0,904,0,0],["v","Когда мы помирились, слез горячих",0,905,0,0],["v","На нежные ланиты реки льются.",0,905,0,0],["sp","Корифей"],["v","Да, свежая и у меня бежит",0,906,0,0],["v","Вниз по лицу слеза. Довольно бедствий!",0,906,0,0],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["dir","ласково, но не подходя к <span class=\"ch\" data-ch=\"medeya\">Медее</span>"],["v","Мне нравятся, Медея, те слова,",0,907,0,0],["v","Которые я слышу, — улетевших",0,908,0,0],["v","Я не хочу и помнить. Гнев у жен",0,908,0,0],["v","Всегда кипеть готов, когда мужьям",0,909,0,0],["v","Приходится им изменять на ложе.",0,910,0,1],["v","Да, хоть не сразу, все-таки пришла",0,910,0,0],["v","Ты к доброму решению. И скромность",0,911,0,0],["v","В <span class=\"ch\" data-ch=\"medeya\">Медее</span> победила…",0,912,0,0],["sd","(Делает шаг к детям, которые доверчиво и порывисто к нему ласкаются.)"],["v","Вам же, дети,",0,913,4,0],["v","При помощи богов я доказать",0,913,0,0],["v","Свои заботы долгие надеюсь…",0,914,0,0],["v","Когда-нибудь меж первыми людьми",0,915,0,0],["v","Увижу вас в Коринфе… через братьев,",0,916,0,0],["v","Которые родятся.",0,916,0,0],["v","А пока",1,916,0,0],["sd","(лаская их)"],["v","Растите, детки, — дальше ж дело бога,",0,917,0,0],["v","Коль есть такой, что любит вас, и наше;",0,918,0,0],["v","Даст бог, сюда вернетесь в цвете сил",0,919,0,0],["v","И юности и недругам моим",0,920,0,1],["v","Покажете, что расцвели недаром.",0,921,0,0],["sd","(Оборачивается и видит <span class=\"ch\" data-ch=\"medeya\">Медею</span>, которая, закрывшись, тихо плачет.)"],["v","Ба… ты опять за слезы… Не глядишь…",0,922,0,0],["v","И нежные от нас ланиты прячешь…",0,923,0,0],["v","Иль я опять тебе не угодил?",0,924,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["dir","отнимая от глаз вуаль"],["v","О нет, я так… Раздумалась о детях.",0,925,0,1],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["v","Несчастная, иль думать значит плакать?",0,929,0,1],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Ведь я носила их… И вот, когда",0,930,0,1],["v","Ты им желал подольше жить,",0,929,0,0],["sd","(слезы)"],["v","так грустно",0,928,4,0],["v","Мне сделалось; то сбудется ль, Ясон?..",0,927,0,0],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["v","Смелей, жена! Что сказано, устрою.",0,926,0,1],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","О, из твоей не выйду воли я.",0,927,0,0],["v","Мы, жены, так и слабы и слезливы…",0,928,0,0],["v","Ну, будет же об этом… а теперь,",0,932,0,1],["v","Вот видишь ли… Царям земли угодно",0,933,0,0],["v","Меня отсюда выслать, и для нас",0,934,0,0],["v","Такой исход, пожалуй, не из худших…",0,935,0,0],["v","Тебе и им помехою, Ясон,",0,936,0,0],["v","Не буду я, по крайней мере, — тяжко",0,937,0,0],["v","Быть в вечном подозренье.",0,938,0,0],["v","Парус свой",1,938,0,0],["v","Сегодня ж поднимаю. Но <span class=\"ch\" data-ch=\"kreont\">Креонта</span>",0,939,0,0],["v","Ты упроси, чтоб дал хоть сыновьям",0,940,0,1],["v","Он вырасти у их отца, в Коринфе.",0,940,0,0],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["v","Дети приближаются к нему.",0,941,0,0],["v","Что ж? Попросить, пожалуй, я не прочь.",0,942,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Жене вели просить, чтобы малюток",0,943,0,0],["v","Не удалял отец ее твоих.",0,944,0,0],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["dir","лаская детей"],["v","Да, да, его мы убедим, конечно…",0,945,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Коль женщина она, одна из нас…",0,946,0,0],["v","И я приду на помощь вам — подарки",0,947,0,0],["v","Твоей жене пошлю через детей,",0,948,0,0],["v","Я знаю: нет прекрасней в целом мире…",0,949,0,0],["v","Постой… сейчас… Рабыни, кто-нибудь,",0,950,0,1],["v","Там пеплос тонкий есть и диадема.",0,950,0,0],["v","Рабыня быстро уходит в дом.",0,951,0,0],["v","Да, благо ей на долю не одно,",0,952,0,0],["v","А мириады целые достались:",0,953,0,0],["v","На ложе муж, такой, как ты, вельможа,",0,953,0,0],["v","А с ним убор, что Гелий завещал,",0,954,0,0],["v","Отец отца, в наследье поколеньям…",0,955,0,0],["v","Рабыня возвращается с дарами в ларце.",0,956,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["dir","детям, которые отошли от отца и с любопытством разглядывают содержание ларца, ослепительно яркое"],["v","Берите вено это, дети, вы",0,956,0,0],["v","Блаженнейшей царевне и невесте",0,957,0,0],["v","Его снесете. О, завиден дар!",0,958,0,0],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["dir","улыбаясь"],["v","Мотовка! Что нищишь себя? Иль мало",0,959,0,0],["v","Там пеплосов в чертогах у царей",0,960,0,1],["v","Иль золота? Прибереги на случай…",0,960,0,0],["v","Коль сами мы в какой-нибудь цене,",0,961,0,0],["v","Твои дары излишни, я уверен.",0,962,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["dir","передавая ларец дядьке, который подошел к детям. До того времени он стоял в открытой правой двери, наблюдая за сценой и изредка обмениваясь с хором впечатлениями посредством взглядов и мимики"],["v","Не говори… Богов и тех дары,",0,963,0,0],["v","Я слышала, склоняют. Сколько надо",0,963,0,0],["v","Прекрасных слов, чтоб слиток золотой",0,964,0,0],["v","Перетянуть… к счастливице невесте",0,965,0,0],["v","И мой убор пойдет… Так молода —",0,966,0,0],["v","И царствует…",0,966,0,0],["v","О, чтоб остались дети,",1,966,0,0],["v","Что золото? Я отдала бы жизнь…",0,967,0,0],["sd","(К детям.)"],["v","Ну, дети, вы пойдете в дом богатый,",0,968,0,0],["v","К жене отца и молодой моей",0,969,0,0],["v","Царице, так смотрите ж, хорошенько",0,970,0,1],["v","Ее вы умоляйте, чтобы, дар",0,970,0,0],["v","Уважив мой, оставили с отцом вас…",0,971,0,0],["v","А главное, глядите, чтоб убор",0,972,0,0],["v","Она сама взяла… Ну, поскорее.",0,973,0,0],["v","Ответа я нетерпеливо жду,",0,974,0,0],["v","И доброго, конечно. С богом, дети!",0,975,0,0],["sd","(Жестом прощается с детьми и <span class=\"ch\" data-ch=\"yason\">Ясоном</span>, которые уходят по направлению дворца, в сопровождении дядьки, несущего ларец.)"],["sp","Хор"],["str","Строфа I"],["v","О дети! Уж ночь вас одела.",0,976,0,0],["v","Кровавой стопою отмщенья",0,977,0,0],["v","Ужасное близится дело:",0,978,0,0],["v","Повязка в руках заблестела.",0,979,0,0],["v","Минута — Аидом обвит,",0,980,0,1],["v","И узел волос заблестит…",0,981,0,0],["str","Антистрофа I"],["v","Но ризы божественным чарам",0,982,0,0],["v","И розам венца золотого",0,983,0,0],["v","Невесту лелеять недаром:",0,984,0,0],["v","Ей ложе Аида готово,",0,985,0,0],["v","И муки снедающим жаром",0,986,0,0],["v","Охватит несчастную сеть,",0,987,0,0],["v","Гореть она будет, гореть…",0,988,0,0],["sd","Строфа II 990 Ты, о горький жених, о царский избранник, Разве не видишь, Что нож над детьми заносят, Что факел поднес ты к самым Ризам невесты? О, как далек ты сердцем, Муж, от судьбы решенной!"],["str","Антистрофа II"],["v","Вместе плачу с тобою, вместе, Медея,",0,989,0,0],["v","Детоубийца,",0,990,1,0],["v","О горькая мать Леонидов!",0,991,0,0],["v","Ты брачного ради ложа",0,992,0,0],["v","Крови их хочешь",0,993,1,0],["v","За то, что муж безбожно",0,1000,0,1],["v","Взял невесту другую.",0,1000,1,0],["act","Исход","a6",""],["scene","Явление одиннадцатое","s15",6,15],["sd","Дядька приходит справа, поспешно и радостный, с ним дети. Дядька, <span class=\"ch\" data-ch=\"medeya\">Медея</span> и хор."],["sp","Дядька"],["v","О госпожа! Детей не изгоняют.",0,1001,0,0],["v","Дары от них царевна приняла",0,1002,0,0],["v","С улыбкой и обеими руками,",0,1003,0,0],["v","С малютками отныне мир. Но, ба!",0,1004,0,0],["v","Что вижу? Это счастие <span class=\"ch\" data-ch=\"medeya\">Медею</span>",0,1005,0,0],["v","Расстроило…",0,1005,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Ай… ай… ай… ай… ай… ай…",0,1006,0,0],["sp","Дядька"],["v","К моим вестям слова те не подходят.",0,1007,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["dir","закрывая лицо руками"],["v","Ай… ай… ай… ай…",0,1008,0,0],["sp","Дядька"],["v","Я возвестил беду,",0,1009,0,0],["v","Считая весть отрадною, должно быть…",0,1010,0,1],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["dir","успокоившись"],["v","Ты передал, что знал, ты ни при чем…",0,1010,0,0],["sp","Дядька"],["v","Но в землю ты глядишь и слезы точишь?",0,1011,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Так быть должно, старик, — нам это бог",0,1012,0,0],["v","И умысел <span class=\"ch\" data-ch=\"medeya\">Медеи</span> злой устроил…",0,1013,0,0],["sd","Пауза."],["sp","Дядька"],["dir","стараясь попасть в тон <span class=\"ch\" data-ch=\"medeya\">Медеи</span>, но решительно не понимая, в чем дело"],["v","Не падай духом, госпожа, авось",0,1014,0,0],["v","Через детей и ты сюда вернешься.",0,1015,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["dir","загадочно"],["v","Других верну я, горькая, сперва.",0,1016,0,0],["sp","Дядька"],["v","Одна ли ты с детьми в разлуке будешь?",0,1017,0,0],["v","Для смертного тяжеле муки нет.",0,1018,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Да, это так… Но в дом войди и детям,",0,1019,0,0],["v","Что нужно на сегодня, приготовь.",0,1020,0,1],["v","Дядька уходит направо, в дверь.",0,1020,0,0],["scene","Явление двенадцатое","s16",6,16],["sd","Медея, дети и хор."],["v","О дети, дети! Есть у вас и город",0,1021,0,0],["v","Теперь, и дом, — там поселитесь вы",0,1022,0,0],["v","Без матери несчастной… навсегда…",0,1023,0,0],["v","А я уйду в изгнание, в другую",0,1023,0,0],["v","Страну и счастья вашего ни видеть,",0,1024,0,0],["v","Ни разделять не буду, ваших жен",0,1025,0,0],["v","И свадеб ваших не увижу, вам",0,1026,0,0],["v","Не уберу и ложа, даже факел",0,1026,0,0],["v","Не матери рука поднимет. О,<a class=\"nr\" href=\"#n-k27\" data-n=\"k27\" aria-label=\"Примечание 27\">27</a>",0,1027,0,0],["v","О горькая, о гордая <span class=\"ch\" data-ch=\"medeya\">Медея</span>!",0,1028,0,0],["v","Зачем же вас кормила я, душой",0,1029,0,0],["v","За вас болела, телом изнывала",0,1030,0,1],["v","И столько мук подъяла, чтобы вам",0,1030,0,0],["v","Отдать сиянье солнца?.. Я надеждой",0,1031,0,0],["v","Жила, что вы на старости меня",0,1032,0,0],["v","Поддержите, а мертвую своими",0,1033,0,0],["v","Оденете руками. И погибла",0,1034,0,0],["v","Та сладкая мечта.",0,1035,0,0],["v","Чужая вам,",1,1035,0,0],["v","Я буду дни влачить. И никогда уж,",0,1036,0,0],["v","Сменивши жизнь иною, вам меня,",0,1037,0,0],["v","Которая носила вас, не видеть…",0,1038,0,0],["v","Глазами этими.",0,1039,0,0],["sd","(Привлекает к себе детей, которые веселы, еще полные воспоминаний о своей прогулке.)"],["v","Вы на меня глядите и смеетесь",0,1040,0,1],["v","Последним вашим смехом?.. Ай… ай… ай…",0,1040,0,0],["v","Что ж это я задумала?",0,1041,0,0],["sd","(Опускает руки.)"],["v","Упало",0,1042,4,0],["v","И сердце у меня, когда их лиц",0,1043,0,0],["v","Я светлую улыбку вижу, жены.",0,1043,0,0],["v","Я не смогу, о нет… Ты сгибни, гнет",0,1044,0,0],["v","Ужасного решенья!.. Я с собою",0,1045,0,0],["v","Возьму детей… Безумно покупать",0,1046,0,0],["v","Ясоновы страдания своими",0,1046,0,0],["v","И по двойной цене… О, никогда…",0,1047,0,0],["v","Тот план забыт… Забыт… Конечно… Только",0,1048,0,0],["v","Что ж я себе готовлю? А враги?",0,1049,0,0],["v","Смеяться им я волю дам, и руки",0,1050,0,1],["v","Их выпустят… без казни?..",0,1050,0,0],["sd","(Выпрямляясь; дети присмирели и смотрят испуганно.)"],["v","Не найду",0,1051,4,0],["v","Решимости?",0,1052,0,0],["v","О стыд, о униженье!",1,1052,0,0],["v","Бояться слов, рожденных слабым сердцем…",0,1052,0,0],["v","Ступайте в дом, вы, дети, и кому",0,1053,0,0],["v","Присутствовать при этой жертве совесть",0,1054,0,0],["v","Его не позволяет, может тоже<a class=\"nr\" href=\"#n-k28\" data-n=\"k28\" aria-label=\"Примечание 28\">28</a>",0,1055,0,0],["v","Уйти… Моя рука уже не дрогнет…",0,1055,0,0],["sd","Дети хотят уйти, но <span class=\"ch\" data-ch=\"medeya\">Медея</span> удерживает и привлекает их к себе каким-то судорожным движением."],["v","Га…",0,1056,0,0],["v","Ты, сердце, это сделаешь?.. О нет,",0,1057,0,0],["v","Оставь детей, несчастная, в изгнанье",0,1057,0,0],["v","Они усладой будут.",0,1058,0,0],["v","Так клянусь же",1,1058,0,0],["v","Аидом я и всей поддонной силой,",0,1059,0,0],["v","Что не видать врагам моих детей,",0,1060,0,1],["v","Покинутых <span class=\"ch\" data-ch=\"medeya\">Медеей</span> на глумленье.",0,1061,0,0],["v","Все сделано… Возврата больше нет…",0,1062,0,0],["v","На голове царевны диадема,",0,1063,0,0],["v","И в пеплосе отравленном моем",0,1064,0,0],["v","Она теперь, я знаю, умирает…",0,1065,0,0],["v","Мне ж новый путь открылся… Новый… Да…",0,1066,0,0],["v","Но только прежде…",0,1067,0,0],["sd","(Порывисто обнимая детей и целуя их руки и лица.)"],["v","Дети, дайте руки,",0,1068,4,0],["v","Я их к губам прижать хочу… Рука",0,1070,0,1],["v","Любимая, вы, волосы, вы, губы,",0,1070,0,0],["v","И ты, лицо, какое у царей",0,1071,0,0],["v","Бывает только… Вы найдете счастье",0,1072,0,0],["v","Не здесь, увы! Украдено отцом",0,1073,0,0],["v","Оно у нас… О, сладкие объятья,",0,1073,0,0],["v","Щека такая нежная и уст",0,1074,0,0],["v","Отрадное дыханье…",0,1075,0,0],["sd","(Целует детей, потом с силой отрывается от них, слабо отталкивает их и закрывает лицо руками.)"],["v","Уходите,",0,1076,0,0],["v","Скорее уходите…",0,1076,0,0],["sd","Дети убегают, оглядываясь на мать и что-то говоря друг другу."],["v","Силы нет",1,1076,0,0],["v","Глядеть на вас. Раздавлена я мукой…",0,1077,0,0],["v","На что дерзаю, вижу… Только гнев",0,1078,0,0],["v","Сильней меня, и нет для рода смертных",0,1079,0,0],["v","Свирепей и усердней палача…",0,1080,0,1],["sd","(Уходит в среднюю дверь.)"],["sp","Хор"],["v","Люблю я тонкие сети",0,1080,0,0],["v","Науки, люблю я выше",0,1081,0,0],["v","Умом воспарять, чем женам",0,1082,0,0],["v","Обычай людей дозволяет…",0,1083,0,0],["v","Есть муза, которой мудрость",0,1084,0,0],["v","И наша отрадна; жены",0,1085,0,0],["v","Не все ее видят улыбку —",0,1085,0,0],["v","Меж тысяч одну найдешь ты, —",0,1086,0,0],["v","Но ум для науки женский",0,1087,0,0],["v","Нельзя же назвать закрытым.",0,1088,0,0],["v","Я думала долго, и тот,",0,1089,0,0],["v","По-моему, смертный счастлив,",0,1090,0,1],["v","Который, до жен не касаясь,",0,1090,0,0],["v","Детей не рождал; такие",0,1091,0,0],["v","Не знают люди, затем что",0,1092,0,0],["v","Им жизнь не сказала, сладки ль",0,1093,0,0],["v","Дети отцам иль только",0,1094,0,0],["v","С ними одно мученье…",0,1095,0,0],["v","Незнанье ж от них удаляет",0,1096,0,0],["v","Много страданий; а те,",0,1097,0,0],["v","Которым сладкое это",0,1098,0,0],["v","Украсило дом растенье,",0,1099,0,0],["v","Заботой крушатся всечасно,",0,1100,0,1],["v","Как выходить нежных, откуда",0,1100,0,0],["v","Взять для них средства к жизни,",0,1101,0,0],["v","Да и кого они р<em>о</em>стят,",0,1102,0,0],["v","Достойных людей иль негодных,",0,1103,0,0],["v","Разве отцы знают?",0,1103,0,0],["v","Но из несчастий горше",0,1104,0,0],["v","Нет одного и ужасней.",0,1105,0,0],["v","Пусть денег отец накопит,",0,1106,0,0],["v","Пусть дети цветут красою,",0,1106,0,0],["v","И доблесть сердца им сковала,",0,1107,0,0],["v","Но если налетом вырвет",0,1108,0,0],["v","Из дома их демон смерти",0,1109,0,0],["v","И бросит в юдоль Аида,",0,1110,0,1],["v","Чем выкупить можно эту",0,1111,0,0],["v","Тяжелую рану и есть ли",0,1112,0,0],["v","Больнее печаль этой платы",0,1113,0,0],["v","За сладкое право рожденья?..",0,1114,0,0],["scene","Явление тринадцатое","s17",6,17],["sd","<span class=\"ch\" data-ch=\"medeya\">Медея</span> выходит из средних дверей. <span class=\"ch\" data-ch=\"medeya\">Медея</span> и хор; после первых 5 стихов -вестник справа."],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Я заждалась, подруги, чтоб судьба",0,1115,0,0],["v","Свое сказала слово — в нетерпенье",0,1116,0,0],["v","Известие зову я… Вот как раз",0,1117,0,0],["v","Из спутников Леоновых один;",0,1118,0,0],["v","Как дышит трудно, он — с недоброй вестью.",0,1120,0,1],["sp","Вестник"],["dir","запыхавшись; одежда в беспорядке"],["v","Беги, беги, <span class=\"ch\" data-ch=\"medeya\">Медея</span>; ни ладьей",0,1121,0,0],["v","Пренебрегать не надо, ни повозкой;",0,1122,0,0],["v","Не по морю, так посуху беги…",0,1123,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["dir","дерзко"],["v","А почему же я должна бежать?",0,1124,0,0],["sp","Вестник"],["dir","сразу выпрастывая мешок"],["v","Царевна только что скончалась, следом",0,1125,0,0],["v","И царь-отец — от яда твоего.",0,1126,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Счастливое известие… Считайся",0,1127,0,0],["v","Между друзей <span class=\"ch\" data-ch=\"medeya\">Медеи</span> с этих пор.",0,1128,0,0],["sp","Вестник"],["v","Что говоришь? Здорова ты иль бредишь?",0,1129,0,0],["v","Царев очаг погас, а у тебя",0,1130,0,1],["v","Смех на устах и хоть бы капля страха.",0,1130,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Нашелся бы на это и ответ…",0,1131,0,0],["v","Но не спеши, приятель, по порядку",0,1132,0,0],["v","Нам опиши их смерть, и чем она",0,1133,0,0],["v","Ужаснее была, тем сердцу слаще.",0,1134,0,0],["sp","Вестник"],["v","Когда твоих детей, Медея, складень",0,1135,0,0],["v","Двустворчатый и их отец прошли",0,1136,0,0],["v","К царевне в спальню, радость пробежала",0,1137,0,0],["v","По всем сердцам — страдали за тебя",0,1138,0,0],["v","Мы, верные рабы… А тут рассказы",0,1139,0,0],["v","Пошли, что ссора кончилась у вас.",0,1140,0,1],["v","Кто у детей целует руки, кто",0,1140,0,0],["v","Их волосы целует золотые;",0,1141,0,0],["v","На радостях я до покоев женских",0,1142,0,0],["v","Тогда проник, любуясь на детей.",0,1143,0,0],["v","Там госпожа, которой мы дивиться",0,1144,0,0],["v","Вместо тебя должны теперь, детей",0,1145,0,0],["v","Твоих сперва, должно быть, не видала;",0,1145,0,0],["v","Она <span class=\"ch\" data-ch=\"yason\">Ясону</span> только улыбнулась,",0,1146,0,0],["v","Но тотчас же фатой себе глаза",0,1147,0,0],["v","И нежные ланиты закрывает;",0,1148,0,0],["v","Приход детей смутил ее, а муж",0,1149,0,0],["v","Ей говорит: \"О, ты не будешь злою",0,1150,0,1],["v","С моими близкими, покинь свой гнев",0,1150,0,0],["v","И посмотри на них; одни и те же",0,1151,0,0],["v","У нас друзья, не правда ли? Дары",0,1152,0,0],["v","Приняв от них, ты у отца попросишь",0,1153,0,0],["v","Освободить их от изгнанья; я",0,1154,0,0],["v","Того хочу\". Царевна же, увидев",0,1155,0,0],["v","В руках детей убор, без дальних слов",0,1156,0,0],["v","Все обещала мужу. А едва",0,1157,0,0],["v","<span class=\"ch\" data-ch=\"yason\">Ясон</span> детей увел, она расшитый",0,1158,0,0],["v","Набросила уж пеплос и, волну",0,1159,0,0],["v","Волос златой прижавши диадемой,",0,1160,0,1],["v","Пред зеркалом блестящим начала",0,1160,0,0],["v","Их оправлять, и тени красоты",0,1161,0,0],["v","Сияющей царевна улыбалась,",0,1162,0,0],["v","И, с кресла встав, потом она прошлась",0,1162,0,0],["v","По комнате, и, белыми ногами",0,1163,0,0],["v","Ступая так кокетливо, своим",0,1164,0,0],["v","Убором восхищалась, и не раз,",0,1164,0,0],["v","На цыпочки привстав, до самых пяток",0,1165,0,0],["v","Глазам она давала добежать.",0,1166,0,0],["v","Но зрелище внезапно изменилось",0,1166,0,0],["v","В ужасную картину. И с ее",0,1167,0,0],["v","Ланит сбежала краска, видим…",0,1168,0,0],["v","После",1,1168,0,0],["v","Царевна зашаталась, задрожали",0,1168,0,0],["v","У ней колени, и едва-едва…",0,1169,0,0],["v","Чтоб не упасть, могла дойти до кресла…",0,1170,0,1],["v","Тут старая рабыня, Пана ль гнев<a class=\"nr\" href=\"#n-k29\" data-n=\"k29\" aria-label=\"Примечание 29\">29</a>",0,1170,0,0],["v","Попритчился ей иль иного бога,",0,1171,0,0],["v","Ну голосить… Но… ужас… вот меж губ",0,1172,0,0],["v","Царевниных комок явился пены,",0,1173,0,0],["v","Зрачки из глаз исчезли, а в лице",0,1174,0,0],["v","Не стало ни кровинки, — тут старуха",0,1175,0,0],["v","И причитать забыла, тут она",0,1176,0,0],["v","Со стоном зарыдала. Вмиг рабыни",0,1177,0,0],["v","Одна к отцу, другая к мужу с вестью",0,1178,0,0],["v","О бедствии — и тотчас весь чертог",0,1179,0,0],["v","И топотом наполнился, и криком…",0,1180,0,1],["v","И сколько на бегах возьмет атлет,",0,1180,0,0],["v","Чтоб, обогнув мету, вернуться к месту,",0,1181,0,0],["v","Когда прошло минут, то изваянье,",0,1182,0,0],["v","Слепое и немое, ожило:",0,1183,0,0],["v","Она со стоном возвратилась к жизни",0,1183,0,0],["v","Болезненным.",0,1184,0,0],["v","И два недуга враз<a class=\"nr\" href=\"#n-k30\" data-n=\"k30\" aria-label=\"Примечание 30\">30</a>",1,1184,0,0],["v","На жалкую невесту ополчились:",0,1185,0,0],["v","Венец на волосах ее златой",0,1186,0,0],["v","Был пламенем охвачен жадным, риза ж,",0,1186,0,0],["v","Твоих детей подарок, тело ей",0,1187,0,0],["v","Терзала белое, несчастной… Вижу: с места",0,1188,0,0],["v","Вдруг сорвалась и — ужас! Вся в огне",0,1189,0,0],["v","И силится стряхнуть она движеньем",0,1190,0,1],["v","С волос венец, а он как бы прирос;",0,1191,0,0],["v","И только пуще пламя от попыток",0,1192,0,0],["v","Ее растет и блещет. Наконец,",0,1193,0,0],["v","Осилена, она упала, мукой…",0,1194,0,0],["v","Отец и тот ее бы не узнал:",0,1195,0,0],["v","Ни места глаз, ни дивных очертаний",0,1196,0,0],["v","Не различить уж было, только кровь",0,1197,0,0],["v","С волос ее катилась и кипела,",0,1198,0,0],["v","Мешаясь с пламенем, а мясо от костей,",0,1200,0,1],["v","Напоено отравою незримой,",0,1200,0,0],["v","Сквозь кожу выступало — по коре",0,1201,0,0],["v","Еловой так сочатся слезы. Ужас",0,1202,0,0],["v","Нас охватил, и не дерзали мы",0,1202,0,0],["v","До мертвой прикоснуться. Мы угрозе",0,1203,0,0],["v","Судьбы внимали молча. — Ничего",0,1204,0,0],["v","Не знал отец, когда входил, и сразу",0,1204,0,0],["v","Увидел труп. Рыдая, он упал",0,1205,0,0],["v","На мертвую, и обнял, и целует",0,1206,0,0],["v","Свое дитя и говорит: \"О дочь",0,1206,0,0],["v","Несчастная! Кто из богов позорной",0,1207,0,0],["v","Твоей желал кончины и зачем",0,1208,0,0],["v","Осиротил он старую могилу,",0,1208,0,0],["v","Взяв у отца цветок его? С тобой",0,1209,0,0],["v","Пусть вместе бы убит я был\". Он кончил",0,1210,0,1],["v","И хочет встать, но тело, точно плющ,",0,1210,0,0],["v","Которым лавр опутан, прирастает",0,1211,0,0],["v","К нетронутой одежде, — и борьба",0,1212,0,0],["v","Тут началась ужасная: он хочет",0,1213,0,0],["v","Подняться на колени, а мертвец",0,1214,0,0],["v","Его к себе влечет. Усилья ж только",0,1215,0,0],["v","У старца клочья мяса отдирают…",0,1216,0,0],["v","Попытки все слабее, гаснет царь",0,1217,0,0],["v","И испускает дух, не властен больше",0,1218,0,0],["v","Сопротивляться муке. Так они",0,1219,0,0],["v","Там и лежат — старик и дочь, — бездушны",0,1220,0,1],["v","И вместе, — слез желанная юдоль.",0,1220,0,0],["sd","Пауза."],["v","А о тебе что я скажу? Сама",0,1221,0,0],["v","Познаешь ты весь ужас дерзновенья…",0,1222,0,0],["v","Да, наша жизнь лишь тень: не в первый раз",0,1223,0,0],["v","Я в этом убеждаюсь. Не боюсь",0,1224,0,0],["v","Добавить я еще, что, кто считает",0,1225,0,0],["v","Иль мудрецом себя, или глубоко",0,1226,0,0],["v","Проникшим тайну жизни, заслужил",0,1227,0,0],["v","Название безумца. Счастлив смертный",0,1228,0,0],["v","Не может быть. Когда к нему плывет",0,1229,0,0],["v","Богатство — он удачник, но и только…",0,1230,0,1],["sd","(Уходит в дверь налево.)"],["scene","Явление четырнадцатое","s18",6,18],["sd","Без вестника."],["sp","Корифей"],["v","Да, много зол — заслуженных, увы! —",0,1231,0,0],["v","Бог наложил сегодня на <span class=\"ch\" data-ch=\"yason\">Ясона</span>…",0,1232,0,0],["v","Ты ж, бедная <span class=\"ch\" data-ch=\"kreont\">Креонта</span> дочь, тебя",0,1233,0,0],["v","Жалеем мы: тебе <span class=\"ch\" data-ch=\"yason\">Ясонов</span> брак",0,1234,0,0],["v","Аидовы ворота отверзает…",0,1235,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Так… решено, подруги… Я сейчас",0,1236,0,0],["v","Прикончу их и уберусь отсюда,",0,1237,0,0],["v","Иначе сделает другая и моей",0,1238,0,0],["v","Враждебнее рука, но то же; жребий",0,1240,0,1],["v","Им умереть теперь. Пускай же мать",0,1240,0,0],["v","Сама его и выполнит.",0,1241,0,0],["v","Ты, сердце,",1,1241,0,0],["v","Вооружись! Зачем мы медлим? Трус",0,1242,0,0],["v","Пред ужасом один лишь неизбежным",0,1243,0,0],["v","Еще стоит в раздумье. Ты, рука",0,1243,0,0],["v","Злосчастная, за нож берись… Медея,",0,1244,0,0],["v","Вот тот барьер, откуда ты начнешь",0,1245,0,0],["v","Печальный бег сейчас. О, не давай",0,1246,0,0],["v","Себя сломить воспоминаньям, мукой",0,1246,0,0],["v","И негой полным; на сегодня ты",0,1247,0,0],["v","Не мать им, нет, но завтра сердце плачем",0,1248,0,0],["v","Насытишь ты. Ты убиваешь их",0,1249,0,0],["v","И любишь. О, как я несчастна, жены.",0,1250,0,1],["sd","(Быстро уходит в среднюю дверь не оборачиваясь.)"],["sd","Слышится стук запоров. Между тем близок закат. Солнце, приближаясь к горизонту, кажется больше и ближе к земле."],["sp","Хор"],["str","Строфа I"],["v","И<em>о</em>! Земля, ты светлый луч,",0,1250,0,0],["v","От Гелия идущий, о, глядите,",0,1251,0,0],["v","Глядите на злодейку,",0,1252,0,0],["v","Пока рука ее не пролила",0,1252,0,0],["v","Крови детей…",0,1253,0,0],["v","О Солнце, не давай,",0,1254,0,0],["v","Чтоб на землю кровь бога<a class=\"nr\" href=\"#n-k31\" data-n=\"k31\" aria-label=\"Примечание 31\">31</a>",0,1255,0,0],["v","Текла из-под руки,",0,1255,0,0],["v","Подвластной смерти;",0,1256,0,0],["v","Ты, Зевса свет, гони",0,1257,0,0],["v","Эринию из этого чертога,",0,1257,0,0],["v","Которой мысли",0,1258,0,0],["v","Наполнил демон мести",0,1259,0,0],["v","Кровавыми парами.<a class=\"nr\" href=\"#n-k32\" data-n=\"k32\" aria-label=\"Примечание 32\">32</a>",0,1260,0,1],["str","Антистрофа I"],["v","Напрасно ты из-за детей",0,1260,0,0],["v","Страдала и напрасно их рождала.",0,1261,0,0],["v","Те синие утесы,",0,1262,0,0],["v","Как сторожей суровых миновав,",0,1262,0,0],["v","Медея, мать",0,1263,0,0],["v","Несчастная, с душой,",0,1264,0,0],["v","Давимой гневом тяжким,",0,1265,0,0],["v","Зачем влачишься ты",0,1265,0,0],["v","К убийству снова,",0,1266,0,0],["v","Едва одно свершив?",0,1267,0,0],["v","Безумная! О, горе смертным,",0,1267,0,0],["v","Покрытым кровью.",0,1268,0,0],["v","К богам она взывает,",0,1269,0,0],["v","И боги щедро платят…",0,1270,0,1],["v","Дети за сценой плачут и кричат.",0,1270,0,0],["sp","Хор"],["str","Строфа II"],["v","Голоса детей… Послушай,",0,1271,0,0],["v","О преступная! О, злой",0,1272,0,0],["v","И жены ужасный жребий!",0,1273,0,0],["sd","Один детский голос"],["v","Ай… ай… о, как от матери спасусь?",0,1273,0,0],["sd","Другой"],["v","Не знаю, милый… Гибнем… Мы погибли…",0,1274,0,0],["sp","Хор"],["v","Поспешим на помощь, сестры;",0,1275,0,0],["v","В дом иду я.",0,1276,0,0],["v","Детские голоса",0,1276,4,0],["v","Скорее, ради бога, — нас убьют…",0,1277,0,0],["v","Железные сейчас сожмут нас сети.",0,1278,0,0],["sp","Хор"],["v","Ты из камня иль железа,",0,1279,0,0],["v","Что свое, жена, рожденье,",0,1280,0,1],["v","Плод любимый убиваешь…",0,1280,0,0],["str","Антистрофа II"],["v","Мне одну хранила память,",0,1281,1,0],["v","Что детей любила, мать,",0,1282,1,0],["v","И сама же их убила…",0,1283,1,0],["v","Ин<em>о</em> в безумии божественном, когда<a class=\"nr\" href=\"#n-k33\" data-n=\"k33\" aria-label=\"Примечание 33\">33</a>",0,1284,0,0],["v","Ее скитаться осудила Гера.",0,1285,0,0],["v","Волны моря смыли только",0,1285,1,0],["v","Пятна крови,",0,1286,1,0],["v","Она ж, с утеса в море соступив,",0,1287,0,0],["v","Двух сыновей теперь могилу делит.",0,1288,0,0],["v","Ужас, ужас ты предельный!",0,1289,1,0],["v","Сколько зерен злодеянья",0,1290,1,1],["v","В ложе мук таится женских…",0,1291,1,0],["scene","Явление пятнадцатое","s19",6,19],["sd","<span class=\"ch\" data-ch=\"yason\">Ясон</span> справа, бледный и злой. За ним в беспорядке свита. Солнце закатилось. Почти темно. <span class=\"ch\" data-ch=\"yason\">Ясон</span> и хор."],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["v","Вы, жены, здесь уже давно, не так ли?",0,1292,0,0],["v","Злодейка где ж? В чертоге заперлась?",0,1293,0,0],["v","Или в бегах <span class=\"ch\" data-ch=\"medeya\">Медея</span>? Только ад",0,1294,0,0],["v","Иль неба высь да крылья птицы разве",0,1295,0,0],["v","Ее спасти могли бы. За тиранов",0,1296,0,0],["v","Она иначе роду их ответит.",0,1297,0,0],["v","Иль, может быть, убив царя земли,",0,1298,0,0],["v","Она себя считает безопасной,",0,1300,0,1],["v","Коли ушла отсюда?..",0,1300,0,0],["v","Но о ней",1,1300,0,0],["v","Я думаю не столько, как о детях:",0,1301,0,0],["v","Ее казнить всегда найдутся руки.",0,1302,0,0],["v","Детей бы лишь спасти, и как бы им",0,1303,0,0],["v","Креонтова родня за материнский",0,1304,0,0],["v","Не мстила грех — вот я чего боюсь.",0,1305,0,0],["sp","Корифей"],["v","О, ты, Ясон, еще не знаешь бедствий",0,1305,0,0],["v","Последнего предела; не звучат",0,1306,0,0],["v","Они еще в твоих словах, несчастный.",0,1307,0,0],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["v","Так где же он? Иль очередь за мной?",0,1308,0,0],["sp","Корифей"],["v","Детей твоих, детей их мать убила.",0,1309,0,0],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["v","Что говоришь? О, смерть, о, злая смерть!",0,1310,0,1],["sp","Корифей"],["v","Их больше нет, их больше нет на свете.",0,1310,0,0],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["v","Убила где ж, при вас или в дому?",0,1311,0,0],["sp","Корифей"],["v","Вели открыть ворота — сам увидишь.",0,1312,0,0],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["dir","идет к средней двери и, видя, что она заперта изнутри —"],["v","Гей! Вы! Долой запоры, с косяков",0,1313,0,0],["v","Срывайте двери — два несчастья видеть",0,1314,0,0],["v","Хочу я, двух убитых и злодейку.<a class=\"nr\" href=\"#n-k34\" data-n=\"k34\" aria-label=\"Примечание 34\">34</a>",0,1315,0,0],["scene","Явление шестнадцатое","s20",6,20],["sd","Сцена наполняется странным оранжевым светом. На альтане колесница, запряженная крылатыми драконами. В ней — <span class=\"ch\" data-ch=\"medeya\">Медея</span>. Она сидит, и у нее на коленях два бледных мальчика с перерезанными горлами."],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Не надо дверь ломать, чтобы найти",0,1316,0,0],["v","Убитых и виновницу убийства —",0,1317,0,0],["v","Меня. Не трать же сил и, если я",0,1318,0,0],["v","Тебе нужна, скажи, чего ты хочешь.",0,1319,0,0],["v","А в руки я тебе не дамся, нет:",0,1320,0,1],["v","От вражьих рук защитой — колесница,",0,1320,0,0],["v","Что Гелий мне послал, отец отца *.",0,1321,0,0],["v","{* Текст, набранный курсивом, пропущен",0,1322,0,0],["v","Ин. Анненским и переведен для издания 1969 г.}",0,1322,0,0],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["dir","перехрипшим от ярости голосом"],["v","О, язва! Нет, богам, и мне, и всем,",0,1323,0,0],["v","Всем людям нет <span class=\"ch\" data-ch=\"medeya\">Медеи</span> ненавистней,",0,1324,0,0],["v","Которая рожденью своему",0,1324,0,0],["v","Дыханье перервать ножом дерзнула",0,1325,0,0],["v","И умереть бездетным мне велит…",0,1326,0,0],["v","И ты еще на солнце и на землю",0,1326,0,0],["v","Решаешься глядеть, глаза свои",0,1327,0,0],["v","Насытивши безбожным дерзновеньем.",0,1328,0,0],["v","О, сгибни ж ты. Прозрел я наконец.",0,1328,0,0],["v","Один слепой мог брать тебя в Элладу",0,1329,0,0],["v","И в свой чертог от варваров… Увы!",0,1330,0,1],["v","Ты предала отца и землю ту,",0,1330,0,0],["v","Которая тебя взрастила, язва!..",0,1331,0,0],["v","Ты демон тот была, которым боги",0,1332,0,0],["v","В меня ударили…",0,1333,0,0],["v","Чтобы попасть",1,1333,0,0],["v","На наш корабль украшенный, ты брата",0,1334,0,0],["v","Зарезала у алтаря. То был",0,1335,0,0],["v","Твой первый шаг. Ты стала мне женой",0,1336,0,0],["v","И принесла детей, и ты же их,",0,1337,0,0],["v","По злобе на соперницу, убила.",0,1338,0,0],["v","Во всей Элладе нет подобных жен,",0,1339,0,0],["v","А между тем я отдал предпочтенье",0,1340,0,1],["v","Тебе пред всеми женами, и вот",0,1340,0,0],["v","Несчастлив я и разорен… Ты львица,",0,1341,0,0],["v","А не жена, и если сердце есть",0,1342,0,0],["v","У Скиллы, так она тебя добрее.",0,1343,0,0],["v","Но что тебе укоры? Мириады<a class=\"nr\" href=\"#n-k35\" data-n=\"k35\" aria-label=\"Примечание 35\">35</a>",0,1344,0,0],["v","Их будь меж уст, для дерзости твоей",0,1345,0,0],["v","Они — ничто. Сгинь с глаз моих, убийца",0,1346,0,0],["v","Детей бесстыжая! Оставь меня стонать.",0,1347,0,0],["v","Женой не насладился и детей,",0,1348,0,0],["v","Рожденных мной, взлелеянных, увы,",0,1349,0,0],["v","Не обниму живыми! Все погибло.",0,1350,0,1],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Я многое сказала бы тебе",0,1350,0,0],["v","В ответ на это. Но Кронид-отец",0,1351,0,0],["v","Все знает, что я вынесла и что",0,1352,0,0],["v","Я сделала. Тебе же не придется,",0,1353,0,0],["v","Нам опозорив ложе, услаждать",0,1354,0,0],["v","Себе, Ясон, существованье, чтобы",0,1355,0,0],["v","Смеялись над <span class=\"ch\" data-ch=\"medeya\">Медеей</span>. Ни твоя",0,1355,0,0],["v","Царевна, ни отец, ее вручавший,",0,1356,0,0],["v","Изгнать меня, как видишь, не могли.",0,1357,0,0],["v","Ты можешь звать меня как хочешь: львицей",0,1358,0,0],["v","Иль Скиллою Тирренской; твоего",0,1359,0,0],["v","Коснулась сердца я и знаю — больно…",0,1360,0,1],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["v","И своего. Тем самым — двух сердец.",0,1361,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Легка мне боль, коль ею смех твой прерван.",0,1362,0,0],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["v","О дети, вы злодейкой рождены.",0,1363,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","И вас сгубил недуг отцовский, дети!",0,1364,0,0],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["v","Моя рука не убивала их.",0,1365,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Но грех убил и новый брак, невинных.",0,1366,0,0],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["v","Из ревности малюток заколоть…",0,1367,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Ты думаешь — для женщин это мало?",0,1368,0,0],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["v","Не женщина, змея ты, хуже змей…<a class=\"nr\" href=\"#n-k36\" data-n=\"k36\" aria-label=\"Примечание 36\">36</a>",0,1369,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","И все ж их нет, — и оттого ты страждешь.",0,1370,0,1],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["v","Нет, есть они и матери грозят…",0,1370,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Виновника несчастий знают боги…",0,1371,0,0],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["v","И колдовство проклятое твое.",0,1372,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Ты можешь ненавидеть. Только молча…",0,1373,0,0],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["v","Не слушая. Иль долго разойтись?..<a class=\"nr\" href=\"#n-k37\" data-n=\"k37\" aria-label=\"Примечание 37\">37</a>",0,1374,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","О, я давно горю желаньем этим…",0,1375,0,0],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["v","Дай мне детей, оплакав, схоронить…",0,1376,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","О нет! Моя рука их похоронит.",0,1377,0,0],["v","В священную я рощу унесу",0,1378,0,0],["v","Малюток, Геры Высей, и никто",0,1379,0,0],["v","Там вражеской десницей их могилы",0,1380,0,1],["v","Не осквернит… В Сизифовой же мы",0,1380,0,0],["v","Земле обряд и праздник установим,",0,1381,0,0],["v","Чтоб искупить невинную их кровь…",0,1382,0,0],["v","Я ухожу в пределы Эрехтея…",0,1383,0,0],["v","И с сыном Пандиона разделю,",0,1384,0,0],["v","С <span class=\"ch\" data-ch=\"egey\">Эгеем</span>, кров его. Тебе ж осталось<a class=\"nr\" href=\"#n-k38\" data-n=\"k38\" aria-label=\"Примечание 38\">38</a>",0,1385,0,0],["v","Злодейскую запечатлеть свою",0,1385,0,0],["v","Такой же смертью жизнь, а брака видел",0,1386,0,0],["v","Ты горького исход уже, Ясон…",0,1387,0,0],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["v","О, пусть",0,1388,0,0],["v","За детские жизни казнит",0,1389,0,0],["v","Тебя Эриния кровавая и Правда!",0,1390,0,1],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Кто слышит тебя из богов,",0,1390,0,0],["v","Ты, клятвопреступник, — кто слышит?",0,1391,0,0],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["v","Увы! Увы! Детоубийца!",0,1392,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","В чертог воротись. Хоронить",0,1392,0,0],["v","Ступай молодую жену.",0,1393,0,0],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["dir","протягивая руку к колеснице"],["v","О дети, о двое детей,",0,1394,0,0],["v","От вас ухожу я.",0,1395,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Не плачь еще: рано —",0,1395,0,0],["v","Ты старость оплачешь.",0,1396,0,0],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["dir","с прежним движением"],["v","Любимые дети!",0,1397,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Для матери, не для тебя.",1,1397,0,0],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["v","Убийце… нет!<a class=\"nr\" href=\"#n-k39\" data-n=\"k39\" aria-label=\"Примечание 39\">39</a>",0,1397,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Да, и тебе на горе…",1,1397,0,0],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["v","О, как горю я",0,1398,0,0],["v","К устам прижаться,",0,1399,0,0],["v","К устам их детским.",0,1400,0,1],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Ты оттолкнул их…",0,1400,0,0],["v","Теперь и ласки",0,1401,0,0],["v","И поцелуи…",0,1402,0,0],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["dir","преклоняя колена"],["v","О, ради богов… О, дай мне",0,1403,0,0],["v","Их нежное тело",0,1403,0,0],["v","Обнять… только тронуть.",0,1404,0,0],["sp","<span class=\"ch\" data-ch=\"medeya\">Медея</span>"],["v","Ты просишь напрасно.",0,1405,0,0],["sd","Свет бледнеет."],["sp","<span class=\"ch\" data-ch=\"yason\">Ясон</span>"],["dir","вставая"],["v","Зевс, о, ты слышишь ли,",0,1406,0,0],["v","Как эта львица,",0,1406,0,0],["v","Грязная эта убийца,",0,1407,0,0],["v","Что она с нами",0,1408,0,0],["v","Делает; видишь ли?",0,1409,0,0],["v","Свидетелем будь нам,",0,1410,0,1],["v","Что, сколько я мог",0,1411,0,0],["v","И слез у меня",0,1412,0,0],["v","Сколько хватало,",0,1413,0,0],["v","Я умолял ее.",0,1414,0,0],["v","Она ж, убив их,",0,1415,0,0],["v","Нас оттолкнула;",0,1416,0,0],["v","Рукой не дала мне",0,1417,0,0],["v","До них коснуться,",0,1418,0,0],["v","Похоронить их…",0,1419,0,0],["v","О, для того ль,",0,1420,0,0],["v","Дети, рождал вас",0,1421,0,0],["v","Я, чтоб оставить",0,1422,0,0],["v","Мертвых убийце?",0,1423,0,0],["sd","(Падает на землю с плачем. Виденье исчезает.)"],["sp","Хор"],["dir","покидая орхестру"],["v","На Олимпе готовит нам многое Зевс;",0,1424,0,0],["v","Против чаянья, многое боги дают:",0,1425,0,0],["v","Не сбывается то, что ты верным считал,",0,1426,0,0],["v","И нежданному боги находят пути;",0,1427,0,0],["v","Таково пережитое нами.",0,1428,0,0],["h1","Комментарий","comm"],["p","«Медея» была поставлена на Великих Дионисиях в 431 г. до н. э., открывая тетралогию, в которую входили трагедии «Филоктет», «Диктис» и сатировская драма «Жнецы», утерянная уже в александрийскую эпоху. Первую награду завоевал Евфорион, сын Эсхила, вторую — Софокл; Еврипид удостоился третьего места, что при трех соревнующихся было равносильно провалу."],["p","История Медеи является составной частью мифа о походе аргонавтов, известного из наиболее древних литературных памятников — «Илиады» (VII, 468; XXI, 41; ХХIII, 747), «Одиссеи» (XI, 256 сл.; XII, 69 — 72) и Гесиодовой «Теогонии» (956 сл.). Первой дошедшей до нас подробной литературной обработкой этого мифа является обширное повествование в IV Пифийской оде Пиндара (ст. 67-255). В самой трагедии содержатся многочисленные намеки на важнейшие моменты сказания, которые здесь целесообразно вкратце изложить. Когда Ясону, посланному в Колхиду его дядей Пелием, царем Иолка в Фессалии, пришлось вступить в бой с огнедышащими быками и драконом, сторожившим золотое руно, полюбившая его Медея помогла ему укротить быков и дракона, а сама решила последовать за ним в Грецию (ст. 478 — 485, 502 сл.). Чтобы задержать своих родных, преследовавших аргонавтов, Медея при отплытии из Колхиды убила захваченного ею брата (ст. 167, 1334) и разбросала куски его тела по берегу; пока потрясенные родственники собирали растерзанные члены юноши, аргонавты успели отплыть. Прибыв в Иолк уже в качестве супруги Ясона, Медея уговорила дочерей Пелия совершить волшебный обряд, который должен был вернуть ему молодость, но коварно обманула их, и старый царь умер мучительной смертью (ст. 9 сл., 486 сл., 504 сл.), после чего Ясону с женой и сыновьями пришлось искать приюта в Коринфе (ст. 10 — 13), где Ясон и задумал жениться на дочери местного царя Креонта (ст. 551 — 554). Оскорбленная Медея, решив отомстить сопернице, послала ей через своих детей отравленный наряд и, когда стало известно о гибели царевны, бежала из Коринфа, оставив сыновей под защитой храма Геры. Однако коринфяне не посчитались с неприкосновенностью храма и в гневе убили детей, за что впоследствии должны были ежегодно приносить искупительную жертву. Реминисценции этого варианта мифа в ст. 1304, 1379 — 1383 не получают удовлетворительного объяснения, поскольку Еврипид видоизменил традиционное сказание, сделав виновницей гибели детей самое Медею."],["ed","В.Н. Ярхо"],["note","k1"],["note","k2"],["note","k3"],["note","k4"],["note","k5"],["note","k6"],["note","k7"],["note","k8"],["note","k9"],["note","k10"],["note","k11"],["note","k12"],["note","k13"],["note","k14"],["note","k15"],["note","k16"],["note","k17"],["note","k18"],["note","k19"],["note","k20"],["note","k21"],["note","k22"],["note","k23"],["note","k24"],["note","k25"],["note","k26"],["note","k27"],["note","k28"],["note","k29"],["note","k30"],["note","k31"],["note","k32"],["note","k33"],["note","k34"],["note","k35"],["note","k36"],["note","k37"],["note","k38"],["note","k39"]],"n":{"k1":["Ст. 2. Лазурные утесы.","По дороге за золотым руном корабль Арго должен был миновать Симплегады — сталкивающиеся морские скалы."],"k2":["Ст. 40-43","Современные издатели считают эти стихи позднейшей вставкой в текст оригинала."],"k3":["Ст. 65-66. Касаясь бороды, тебя молю…","Умоляющий касался рукой подбородка человека, к которому обращался с просьбой."],"k4":["Ст. 68. Камешки","место, где собирались любители игры в камешки, напоминающей игру в кости или в шашки. Пирена — источник в Коринфе."],"k5":["Ст. 95. Парод.","Здесь Анненский называет так не только вступительную песнь хора, но и первую песенную сцену между актерами, ей предшествующую."],"k6":["Ст. 112-113","По замечанию античного комментатора, Медея произносит эти слова при виде детей, входящих в дом."],"k7":["Ст. 135. Чрез двери двойные…","Вопли Медеи проникают через дверь, отделяющую женскую половину дома от центрального зала, и через дверь, выходящую из дома на площадь."],"k8":["Ст. 140. …ложе тиранов… — Тиран","в первоначальном значении слова — правитель, не имеющий наследственных прав на престол. Здесь тиран значит царь."],"k9":["Ст. 160. Кронид","Зевс, сын Крона; Фемида — олицетворение справедливости; Зевс и Фемида считались покровителями клятвы, карающими за ее нарушение. Ср. ст. 492-495."],"k10":["Ст. 215-224","Характерное для Еврипида отступление на моральные темы, вложенное в уста одного из персонажей, обычно вне всякой связи с сюжетной ситуацией. Такой же случай — ст. 294-301."],"k11":["Ст. 231-232. За мужей мы платим.","Браки заключались в Афинах родителями жениха и невесты, как правило, мало интересовавшимися истинными чувствами молодых людей. В этих условиях существенную роль играл размер приданого, которым девушкам приходилось «платить за мужей»."],"k12":["Ст. 405-406. Сизифово потомство","коринфяне; Сизиф считался у греков основателем и первым царем Коринфа… Над Гелиевой кровью ? — Медея — внучка бога солнца Гелиоса."],"k13":["Ст. 421-422","Музы не будут мелодий венчать скорбью о женском коварстве…По замечанию схолиаста, Еврипид намекает здесь на известные стихи из «Одиссеи», XI, 456, и «Трудов и дней» Гесиода, ст. 375; возможна, однако, также полемика с ямбографами — Архилохом и Семонидом Аморгосским, автором сатирической поэмы о различных типах женщин."],"k14":["Ст. 426. Мусагет","Аполлон, предводитель муз."],"k15":["Ст. 431. Менада","букв.: «безумствующая»; здесь: о состоянии Медеи, страстно полюбившей прибывшего за золотым руном Ясона. Ср. ст. 485."],"k16":["Ст. 465-575","Медея и Ясон обмениваются в споре (агоне) почти равными по объему речами, причем каждый из них излагает в строгом порядке доводы, которые должны подтвердить его правоту, и завершает свою речь кратким резюме общего характера. Ср. вступительную статью, с. 26."],"k17":["Ст. 591","…чтобженатым на варварской царевне не остаться… — Довод, не лишенный основания в древних Афинах, где полноправными гражданами считались только дети, родившиеся от брака между гражданами."],"k18":["Ст. 613. Знаки гостиные","таблички, которые разламывались на две половинки, хранившиеся в дружественных семьях; принадлежность к ним определялась по совпадению линии излома."],"k19":["Ст. 653","Сказку сложили эту… — Неточный перевод подлинника, где нет речи о «сказке». Участницы хора, сами видевшие, что творится с Медеей, не испытывают потребности пользоваться рассказом других очевидцев."],"k20":["Ст. 665. Пандион","легендарный афинский царь, отец Эгея."],"k21":["Ст. 668. Серединный храм","храм с прорицалищем Аполлона в Дельфах; в качестве алтаря служил камень конической формы, который греки считали «пупом Земли», т. е. ее центром."],"k22":["Ст. 682 — 684","Для того чтобы попасть из Дельф в Афины, Эгею не было необходимости посещать Коринф, лежащий на Истмийском перешейке. Еврипид мотивирует появление Эгея в Коринфе его желанием навестить Питфея, царя Трезена, расположенного в восточной оконечности Арголиды."],"k23":["Ст. 759. Сын Майи","Гермес, покровитель путников."],"k24":["Ст. 767","В переводе пропущены слова Медеи: «Теперь я надеюсь, что мои враги понесут наказание»."],"k25":["Ст. 797","Я знаю, что врага не насмешу… — неточный перевод. Медея говорит: «Невыносимо быть предметом осмеяния для врагов». Она готова на любое преступление, лишь бы не дать врагам смеяться над собой."],"k26":["Ст. 824-845","Пара строф, прославляющих Афины. Эрехтиды — афиняне, возводившие свой род к легендарному царю Эрехтею. Пиэриды — Музы, родившиеся, по традиционному варианту мифа, в Пиэрии (область в Северной Греции) от Зевса и Мнемосины. Еврипид же называет их родиной Аттику, а матерью — Гармонию. Кефис — река в Аттике."],"k27":["Ст. 1027. …даже факел не матери рука поднимет.","При свадебном обряде мать жениха зажигала факелы, которыми приветствовали приближающуюся процессию с новобрачными."],"k28":["Ст. 1054. …совесть… не позволяет…","В оригинале речь идет не о совести (это понятие только появляется в V в. и встречается у Еврипида еще редко), а о тех, «кому не подобает присутствовать» при этом жертвоприношении."],"k29":["Ст. 1171. Пан","божество, вселявшее в человека, по представлениям греков, внезапный, безотчетный страх."],"k30":["Ст. 1181-1184","И сколько на бегах возьмет атлет… — В подлиннике речь идет о состязании в ходьбе на расстояние в шесть плефров, или в один стадий (около 185 м) — т. е. царевна была без сознания примерно две минуты."],"k31":["Ст. 1256. Кровь бога","См. примеч. к ст. 405-406. <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>Ст. 405-406. Сизифово потомство.</b> коринфяне; Сизиф считался у греков основателем и первым царем Коринфа… Над Гелиевой кровью ? — Медея — внучка бога солнца Гелиоса.</span><!--/xn-->"],"k32":["Ст. 1260. Эриния","Хор называет здесь Эринией Медею, охваченную жаждой кровавой мести Ясону."],"k33":["Ст. 1284 сл. Ино","супруга орхоменского царя Афаманта, взяла на воспитание младенца Диониса, рожденного ее сестрой Семелой от Зевса; за это ревнивая Гера наслала на Ино припадок безумия, во время которого она убила одного из своих сыновей, а другой, спасаясь от матери, бросился в море; Ино последовала за ним. В воде мать и сын превратились в морские божества Левкотею и Палемона (см.: «Ифигения в Тавриде», ст. 270 сл.}. Здесь, однако, Еврипид приписывает Ино убийство обоих детей и опускает вторую часть мифа."],"k34":["Ст. 1316. …и злодейку.","Неточный перевод. В оригинале: «Ту, которую я покараю»."],"k35":["Ст. 1344. Скилла","морское чудовище. Согласно молве она обитала в одной из прибрежных пещер на севере Сицилии, отсюда ее прозвище Тирренская (ст. 1359)."],"k36":["Ст. 1369","Неточный перевод. Смысл оригинала: «Да, для благонравной женщины ревность — оправдание. Но в тебе все — зло». Ср.: «Андромаха», ст. 240-242."],"k37":["Ст. 1374 сл","Неточный перевод. Смысл оригинала: «Ты можешь ненавидеть меня, но и я ненавижу твою злобную речь. — А я твою, — вот и легко найти решение»."],"k38":["Ст. 1384-1385. …разделю, с Эгеем, кров его.","По одной из версий мифа, Медея стала в Афинах женой Эгея."],"k39":["Ст. 1398. Убийце… нет!","непонятный перевод. Смысл оригинала: «И потому ты их убила?»"]},"mainEnd":2193,"c":[{"id":"medeya","name":"Медея","role":"Колхидская царевна, жена Ясона","intro":"Чужеземка, ради Ясона предавшая отца и брата и теперь брошенная им в Коринфе.","arc":"Медея — первая великая героиня Еврипида, в которой страсть оборачивается разрушением. В начале она — оскорблённая жена, к которой сочувственно относятся и хор, и зритель; её речь к коринфянкам о судьбе женщины — одна из самых сильных в античной драме. Но каждое унижение (изгнание, оправдания Ясона) ведёт её к замыслу всё страшнее: от убийства соперницы — к убийству собственных детей, чтобы ударить Ясона в самое сердце. Её знаменитый монолог показывает борьбу материнской любви и гнева; гнев побеждает. В финале она улетает на колеснице Гелиоса — не наказанная, но потерявшая всё.","st":[{"i":347,"p":16,"l":"Пролог · явление третье","t":"Плач за дверью","d":"Из дома слышатся проклятия Медеи себе, детям и мужу; кормилица боится за детей.","c":"Отчаяние уже содержит в себе угрозу детям.","k":false},{"i":425,"p":19,"l":"Действие первое · явление четвертое","t":"Речь к коринфянкам","d":"Выходит спокойной и говорит о горькой доле жены и чужеземки. Просит женщин хранить молчание, если она найдёт путь отомстить.","c":"Из жертвы она становится мстительницей и вербует хор в союзники.","k":true},{"i":573,"p":26,"l":"Действие первое · явление пятое","t":"Один день","d":"Креонт изгоняет её из Коринфа: он боится её мудрости. Медея униженно вымаливает отсрочку на один день.","c":"Этот день ей и нужен; притворство — её первое оружие.","k":false},{"i":969,"p":44,"l":"Действие второе · явление седьмое","t":"Спор с Ясоном","d":"Напоминает, как спасла его в Колхиде и предала ради него родных. Ясон объясняет брак с царевной заботой о семье.","c":"Последняя возможность примирения исчерпана.","k":false},{"i":1199,"p":55,"l":"Действие третье · явление восьмое","t":"Клятва Эгея","d":"Афинский царь, бездетный, обещает ей убежище и клянётся богами не выдавать её.","c":"Есть куда бежать — значит, месть возможна.","k":true},{"i":1288,"p":59,"l":"Действие третье · явление девятое","t":"Замысел","d":"Открывает хору план: отравленные дары царевне — и убийство своих детей, чтобы Ясон остался без потомства.","c":"Решающий поворот: месть требует уничтожить и самое дорогое для неё.","k":true},{"i":1557,"p":71,"l":"Действие четвертое · явление десятое","t":"Притворное примирение","d":"Плача, просит у Ясона прощения и отправляет детей с дарами — пеплосом и венцом — к царевне.","c":"Обман удаётся; путь назад закрывается.","k":false},{"i":1727,"p":79,"l":"Исход · явление двенадцатое","t":"«О дети, дети!»","d":"Прощается с сыновьями; то решает пощадить их, то снова возвращается к замыслу. Гнев оказывается сильнее разума.","c":"Сознаёт, что делает, — и всё же делает.","k":true},{"i":1878,"p":86,"l":"Исход · явление тринадцатое","t":"Весть о гибели царского дома","d":"Вестник рассказывает, как дары сожгли царевну и Креонта. Медея слушает с наслаждением.","c":"Теперь детям не уйти от мести коринфян — последнее оправдание найдено.","k":false},{"i":1971,"p":90,"l":"Исход · явление четырнадцатое","t":"Убийство","d":"Уходит в дом; за сценой слышны крики детей.","c":"","k":false},{"i":2192,"p":100,"l":"Исход · явление шестнадцатое","t":"На колеснице Солнца","d":"Появляется над домом с телами детей на драконовой колеснице Гелиоса, не даёт Ясону даже похоронить их и предсказывает ему бесславную смерть.","c":"Победа, равная полному опустошению.","k":false}],"gen":"Медея"},{"id":"yason","name":"Ясон","role":"Предводитель аргонавтов, муж Медеи","intro":"Герой, ради выгодного брака оставивший жену-чужеземку.","arc":"Ясон у Еврипида — не злодей, а человек рассудка и расчёта, который искренне не понимает, чем провинился. Он рассуждает о выгоде, о благе детей, о том, что дал Медее эллинскую славу. Наказание обрушивается на него полностью: он теряет невесту, тестя, сыновей и будущее.","st":[{"i":969,"p":44,"l":"Действие второе · явление седьмое","t":"Оправдание","d":"Уверяет, что спасли его Эрос и Киприда, а не Медея, и что новый брак выгоден всем, даже её детям.","c":"Его логика холодна, и он не слышит оскорбления.","k":false},{"i":1557,"p":71,"l":"Действие четвертое · явление десятое","t":"Мнимое примирение","d":"Радуется раскаянию жены, хвалит её «разум» и соглашается отнести дары.","c":"Сам становится орудием её мести.","k":false},{"i":2192,"p":100,"l":"Исход · явление шестнадцатое","t":"Всё потеряно","d":"Ломится в дом спасать сыновей и видит Медею с их телами в небе. Проклинает её, просит хоть коснуться детей.","c":"Наказан бездетностью — тем, чем дорожил больше всего.","k":true}],"gen":"Ясон"},{"id":"kreont","name":"Креонт","role":"Царь Коринфа","intro":"Отец невесты Ясона, изгоняющий Медею.","arc":"Креонт боится Медеи и не скрывает этого — и всё же уступает её мольбе о дне отсрочки. Эта жалость стоит жизни ему и дочери.","st":[{"i":573,"p":26,"l":"Действие первое · явление пятое","t":"Изгнание","d":"Объявляет Медее приказ покинуть страну, но поддаётся мольбам и даёт ей один день.","c":"Единственная слабость — роковая.","k":true},{"i":1878,"p":86,"l":"Исход · явление тринадцатое","t":"Гибель","d":"Вестник рассказывает: обнимая сгоревшую дочь, Креонт прилип к отравленному пеплосу и погиб вместе с ней.","c":"","k":false}]},{"id":"egey","name":"Эгей","role":"Царь Афин","intro":"Бездетный царь, возвращающийся от дельфийского оракула.","arc":"Эгей — случайный гость, дающий Медее то, чего ей не хватало: убежище. Его бездетность подсказывает ей, как сильнее всего ранить Ясона.","st":[{"i":1199,"p":55,"l":"Действие третье · явление восьмое","t":"Клятва","d":"Рассказывает о тёмном ответе оракула; Медея обещает излечить его бездетность, и он клянётся принять её в Афинах.","c":"Невольно открывает путь к мести.","k":true}],"gen":"Эгей"}]};
